INSERT INTO public.words (id, word, meaning, detailed_meaning, news_example, hint, related_words) VALUES
(241,'보완재','두 가지 이상의 재화가 함께 사용됨으로써 효용을 얻을 수 있는 재화로, 한 재화의 가격이 하락함에 따라 다른 한 재화의 수요가 증가하는 관계에 있는 재화를 말한다.','두 가지 이상의 재화가 함께 사용됨으로써 효용을 얻을 수 있는 재화로, 한 재화의 가격이 하락함에 따라 다른 한 재화의 수요가 증가하는 관계에 있는 재화를 말한다. 소비자 효용의 관점에서 볼 때, 소비자는 보완재 관계에 있는 두 재화를 따로 소비할 때의 효용이 함께 소비할 때의 효용보다 줄어든다. 승용차와 휘발유, 컴퓨터와 소프트웨어 등은 보완재의 예이다.','','ㅂㅇㅈ',ARRAY['대체재']::text[]),
(242,'보통주자본(Common Equity Tier 1)','보통주자본(CET1; Common Equity Tier 1)은 바젤Ⅲ 자본규제에서 기본자본(Tier 1)을 구성하는 핵심 요소로서, 손실흡수능력이 가장 높은(혹은 은행의 손실을 가장 먼저 보전할…','보통주자본(CET1; Common Equity Tier 1)은 바젤Ⅲ 자본규제에서 기본자본(Tier 1)을 구성하는 핵심 요소로서, 손실흡수능력이 가장 높은(혹은 은행의 손실을 가장 먼저 보전할 수 있는) 자본을 의미하며 보통주 발행으로 인한 자본금·자본잉여금, 이익잉여금, 기타포괄손익누계액 등으로 구성된다. 특정 자본이 보통주자본으로 인정받기 위해서는 청산시 최후 순위일 것, 영구적일 것, 청산시를 제외하고는 상환불가, 재매입 및 상환 또는 발행취소에 대한 기대가 없을 것 등의 요건을 충족해야 한다(참고 「은행업감독업무시행세칙」별표 3). 바젤Ⅲ에서는 보통주자본비율을 위험가중자산의 4.5% 이상이 되도록 규정하고 있다.','','ㅂㅌㅈㅈㅂ()',ARRAY['기본자본(Tier 1)','기타기본자본(Additional Tier 1)']::text[]),
(243,'보편관세','관세란 외국에서 물건을 사오거나 외국으로 물건을 팔 때 부과하는 세금으로 수입관세, 수출관세, 통과관세가 있으며 수출관세와 통과관세는 거의 부과되지 않고 수입관세가 일반적이다.','관세란 외국에서 물건을 사오거나 외국으로 물건을 팔 때 부과하는 세금으로 수입관세, 수출관세, 통과관세가 있으며 수출관세와 통과관세는 거의 부과되지 않고 수입관세가 일반적이다. 관세는 보편관세(uniform tariff)와 차별관세(discriminatory tariff), 상호관세(reciprocal tariff)로도 구분할 수 있는데 특정 품목이나 국가에 국한되지 않고 모든 수입품에 일률적으로 적용되는 관세를 보편관세라고 한다. 차별관세는 수입품의 출처 국가 나 품목에 따라 서로 다른 관세율을 적용하는 것이며, 상호관세는 특정 상대국이 자국 제품에 대해 과도하거나 불공정한 관세를 부과할 경우 이에 대해 동일하거나 유사한 방식으로 관세를 부과하는 경우를 말한다.','','ㅂㅍㄱㅅ','{}'::text[]),
(244,'보호무역주의','보호무역주의는 국가간 무역을 제한하는 경제정책이다.','보호무역주의는 국가간 무역을 제한하는 경제정책이다. 주된 수단으로는 수입금지나 수입할당과 같은 직접적인 방법과 수입상품에 대한 관세 부과와 같은 간접적인 방법 이외에도 덤핑 규제, 보조금 지급, 지적재산권 보호 강화, 환율조작 등 기타 다양한 정부의 규제 등이 있다. 보호무역주의의 목적은 수입으로 경쟁이 유발되는 산업의 생산, 유통,','','ㅂㅎㅁㅇㅈㅇ','{}'::text[]),
(245,'복수통화바스켓제도','고용 등에 손해가 발생하지 않도록 하는 것이다.','고용 등에 손해가 발생하지 않도록 하는 것이다. 한편 보호무역주의는 상대국 수출부문의 생산, 고용은 물론 동 정책을 실행하는 국가의 소비자에게도 물가 상승과 같은 부정적 영향을 미친다. 보호무역주의의 순효과는 경제의 성장이나 발전에 부정적이라는 견해가 지배적이어서 선진국의 주도하에 세계적으로 무역장벽을 낮추는 추세를 보여 왔다. 그러나 일부에서 무역수지 흑자국과 적자국이 뚜렷이 구분·지속되고 수지폭도 점점 커지면서 단기적으로 적자국 수입경쟁 부문의 고용이 심각한 불균형을 보이는 등 부작용도 확대되었다. 이러한 부작용은 특히 2008년 발생한 글로벌 금융위기의 한 원인으로 지적되기도 했다. 최근 미국이 보호무역을 강화하는 정책을 실시하면서 무역갈등이 심화되고 있으나 G20의 대부분 국가는 보호무역주의의 확산을 경계하고 있다.','','ㅂㅅㅌㅎㅂㅅㅋㅈㄷ',ARRAY['고정환율제도/자유변동환율제도','미달러화페그제도']::text[]),
(246,'본드포워드거래','본드포워드거래(Bond Forward Transaction)는 두 당사자가 미래의 일정 시점에 정해진 가격으로 채권(본드)을 매수하거나 매도하기로 약속하는 금융 계약을 말한다.','본드포워드거래(Bond Forward Transaction)는 두 당사자가 미래의 일정 시점에 정해진 가격으로 채권(본드)을 매수하거나 매도하기로 약속하는 금융 계약을 말한다. 이는 거래 당사자 간의 계약을 통해 미래의 특정 시점에 채권을 매수 또는 매도할 가격을 미리 확정하는 장외파생상품이다. 주로 금리 리스크 헤지, 투자 전략 수립 또는 예상 금리 변동에 대한 대비 목적으로 사용되는 본드포워드거래는 현재 시점에서 거래가 이루어지지만 실제 거래는 미래 일정 시점에 계약 당시 정해진 가격으로 성사되므로 금리 변동에 따른 위험을 줄일 수 있다. 또한, 양 당사자 간 신뢰성에 따라 계약이 유지되기 때문에 상대방의 신용상태가 중요하다. 주로 보험사들이 자산 듀레이션을 늘리거나 금리 변동 위험을 헤지하기 위한 수단으로 활용한다. 예를 들어, 보험사가 5년 후 30년 만기 국채를 현재 가격으로 매수하기로 약정하는 본드포워드거래를 체결하는 경우, 5년 후 해당 국채를 현재 가격으로 인수해야 하는데 이러한 거래는 보험사의 자산 듀레이션을 늘리고 금리 상승으로 인한 채권 가격 하락 위험을 헤지하는 효과를 가져올 수 있다. 이 외에도 기업들이 채권 포트폴리오의 금리 위험을 헤지하는 경우나 투자자가 금리 전망에 따라 유리한 가격에 거래를 미리 체결하는 경우에 사용하며, 금융기관이 고객에게 맞춤형 금리 상품을 제공하는 도구로 이용하기도 한다.','','ㅂㄷㅍㅇㄷㄱㄹ','{}'::text[]),
(247,'본원소득','제도단위(비금융법인, 금융법인, 일반정부, 가계 및 비영리단체)가 생산과정에 참여하거나 생산활동에 제공된 자산을 소유함에 따라 발생하는 소득으로 국민순소득(NNI; Net National…','제도단위(비금융법인, 금융법인, 일반정부, 가계 및 비영리단체)가 생산과정에 참여하거나 생산활동에 제공된 자산을 소유함에 따라 발생하는 소득으로 국민순소득(NNI; Net National Income)이라고도 한다. 이는 생산에 의해 창출된 부가가치에서 지급된다. 구체적으로 본원소득은 피용자보수에 영업잉여, 순생산 및 수입세, 순수취재산소득을 더하여 계산한다. 본원소득 = 피용자보수 + 영업잉여 + 순생산 및 수입세 + 순수취재산소득','','ㅂㅇㅅㄷ',ARRAY['영업잉여','피용자보수']::text[]),
(248,'본원소득수지','본원소득수지는 급료 및 임금 수지와 투자소득수지로 구분된다.','본원소득수지는 급료 및 임금 수지와 투자소득수지로 구분된다. 급료 및 임금 수지는 외국인 근로자에게 지급되거나 내국인 해외근로자가 수취하는 금액의 차이를 의미한다. 투자소득수지는 대외 금융자산과 부채의 보유에 의해 발생하는 배당금과 이자 등의 수입과 지급의 차이를 말하는데, 투자 형태에 따라 직접투자소득, 증권투자소득, 기타투자소득으로 세분된다.','','ㅂㅇㅅㄷㅅㅈ',ARRAY['도드-프랭크법']::text[]),
(249,'부가가치','부가가치(Value Added)는 일정 기간 동안에 경제활동주체가 생산활동에 참여하여 새로 이 창출한 가치를 말하는데, 총산출에서 중간투입(소비)을 차감하여 구할 수 있다.','부가가치(Value Added)는 일정 기간 동안에 경제활동주체가 생산활동에 참여하여 새로 이 창출한 가치를 말하는데, 총산출에서 중간투입(소비)을 차감하여 구할 수 있다. 국민소득계정에서는 국민경제 부가가치 총액이 국내총생산이며, 구체적으로는 피용자보수, 영업잉여, 고정자본소모, 생산 및 수입세, 보조금으로 구성되어 있다.','','ㅂㄱㄱㅊ',ARRAY['총산출','글로벌가치사슬(GVC)']::text[]),
(250,'부가가치기준 무역(TiVA)','부가가치기준 무역(TiVA; Trade in Value Added)은 국가간 거래를 재화와 서비스의 각생산 단계에서 창출된 부가가치를 기준으로 파악하는 경제통계이다.','부가가치기준 무역(TiVA; Trade in Value Added)은 국가간 거래를 재화와 서비스의 각생산 단계에서 창출된 부가가치를 기준으로 파악하는 경제통계이다. 최근 글로벌 공급망 (Global Value Chain)이 복잡해지면서 한 제품이 여러 국가의 부품, 설계, 생산과정을 거쳐 완성되고 있다. 따라서 재화와 서비스를 최종 수출 국가 몫으로만 기록(gross value)하는 기존 통계로는 교역이 각국의 경제에 미치는 영향을 분석하는 데 한계가 있다. 전통적인 무역통계는 중간재 거래액이 중복계상(double-counting)되고, 실제로 중간재를 생산하고 가치 창출에 기여한 국가들의 기여도가 정확히 반영되지 않는다. 이에 반해 부가가 치기준의 무역(TiVA)은 상대국 최종수요로 인해 자국에서 창출되는 부가가치의 이입액 (VA-in: 무역통계의 수출과 대응)과 자국의 최종수요로 인해 상대국에서 창출되는 부가 ㅂ 가치의 이출액(VA-out: 무역통계의 수입과 대응)으로 정의한다. 부가가치기준의 무역은 무역 구조를 보다 정확하고 투명하게 파악할 수 있어 국가별 경쟁력 분석, 산업정책 수립, 국제 협상 전략 등에 중요한 기초자료이다. 한편, 부가가치기준 무역은 산업간 거래관계를 통해 상호 의존관계를 분석하는 산업연관분석의 원리를 적용한 국제산업연관표를 활용하여 측정할 수 있다.','','ㅂㄱㄱㅊㄱㅈㅁㅇ()',ARRAY['산업연관표(I/O Tables)']::text[]),
(251,'부가가치유발계수/부가가치계수','소비, 투자, 수출 등 최종수요의 발생이 국내생산을 유발하고 생산 활동에 의해서 부가가 치가 창출되므로 최종수요는 부가가치 창출의 원천이 된다.','소비, 투자, 수출 등 최종수요의 발생이 국내생산을 유발하고 생산 활동에 의해서 부가가 치가 창출되므로 최종수요는 부가가치 창출의 원천이 된다. 이러한 최종수요와 부가가 치와의 기능적 관계는 산업연관표를 이용하면 파악할 수 있다. 부가가치유발계수(Value Added Inducement Coefficients)는 최종수요가 한 단위 발생할 경우 국민경제 전체에서 직·간접으로 유발되는 부가가치 단위를 보여주는 계수이다. 예를 들어 농림수산품의 부가가치계수가 0.9라는 것은 농림수산품에 대한 최종수요가 한 단위 발생할 경우 직· 간접으로 유발되는 부가가치가 0.9단위임을 의미한다. 한편, 각 산업별 부가가치유발계수와 수입유발계수의 합은 항상 1이 된다. 이는 국민경제 전체적으로 보면 최종수요 총액에서 수입을 차감하여 나타낸 지출국민소득이 생산국민소득인 부가가치총액과 항상일치하는 원리와 같은 의미이다.','','ㅂㄱㄱㅊㅇㅂㄱㅅ/ㅂㄱㄱㅊㄱㅅ',ARRAY['생산유발효과']::text[]),
(252,'부동화/무권화','증권의 부동화(Immobilization)란 실물증권을 중앙예탁기관에 집중 보관하여 매매거래 또는 담보거래 등에 따른 증권의 권리이전을 계좌대체 방식으로 처리함으로써 증권의 실물인도의 필요성을…','증권의 부동화(Immobilization)란 실물증권을 중앙예탁기관에 집중 보관하여 매매거래 또는 담보거래 등에 따른 증권의 권리이전을 계좌대체 방식으로 처리함으로써 증권의 실물인도의 필요성을 제거하는 것을 말한다. 증권실물은 이동하지 않고 예탁기관의 장부상 대차기재에 의하여 증권에 대한 권리가 이전됨으로써 실물증권 이동에 따른 분실· 도난의 위험성, 사무처리의 번잡성 등의 문제점을 해결할 수 있다. 한편 증권의 무권화 (Dematerialization)란 유가증권에 대한 권리를 표시하는 실물증권을 발행하지 않고 증권에 대한 권리가 오로지 장부(발행기관 및 중앙예탁기관의 계좌)상에 전자기록 형태로 존재하도록 하여 신주발행 및 증권유통에 따른 권리를 이전하는 것을 말한다.','','ㅂㄷㅎ/ㅁㄱㅎ',ARRAY['중앙예탁기관']::text[]),
(253,'부실채권(NPL)','금융기관의 대출이나 지급보증 중 차주의 재정상황 악화로 인해 회수가 어려운 자산을 의미한다.','금융기관의 대출이나 지급보증 중 차주의 재정상황 악화로 인해 회수가 어려운 자산을 의미한다. 「은행업 감독규정」의 자산건전성 분류기준에 의하면 보유자산의 건전성은 ‘정상’, ‘요주의’, ‘고정’, ‘회수의문’ 및 ‘추정손실’ 등급으로 구분된다. 이 중에 부실채권 (NPL; Non-Performing Loan)은 차주의 채무상환능력 저하가 현재화되거나 원리금 상환이 3개월 이상 연체된 고정 이하 등급(‘회수의문’ 및 ‘추정손실’ 포함)의 대출 등 자산에 해당한다. 부실채권 규모가 증가하게 되면 금융기관은 정상채권보다 더 큰 규모의 대손충당금을 적립해야 하며 이에 따른 비용 증가로 당기순이익이 감소하고 자기자본비율도 하락하게 된다.','','ㅂㅅㅊㄱ()','{}'::text[]),
(254,'부채담보부증권(CDO)','CDO(Collateralized Debt Obligation)란 회사채나 대출채권 등으로 구성된 pool을','CDO(Collateralized Debt Obligation)란 회사채나 대출채권 등으로 구성된 pool을','','ㅂㅊㄷㅂㅂㅈㄱ()','{}'::text[]),
(255,'부채비율','기초자산으로 하여 AAA등급에서 equity(non-rated)까지의 다양한 신용등급으로 발행된 여러 종의 선·후순위 채권을 말하며, 기초자산의 종류에 따라 회사채를 기초자산으로 하는 회사채…','기초자산으로 하여 AAA등급에서 equity(non-rated)까지의 다양한 신용등급으로 발행된 여러 종의 선·후순위 채권을 말하며, 기초자산의 종류에 따라 회사채를 기초자산으로 하는 회사채 담보부증권(CBO; Collateralized Bond Obligation), 대출채권을 기초자산으로 하는 대출채권 담보부증권(CLO; Collateralized Loan Obligation)으로 분류된다. 그리고 발행목적에 따라 주로 은행 등의 금융기관이 재무상태표상에서 위험자산을 제거하기 위하여 발행하는 Balance Sheet CDO와 고수익의 원자산인 대출금, 회사채 등과 선· 후순위 채권 간의 이자차익을 얻기 위해 발행하는 Arbitrage CDO 등이 있다. 미국의 모기지 전문 대출기관들은 2000년대 초중반 부동산 활황을 틈타 대출자금을 조달하기 위하여 모기지 채권이나 주택저당증권(MBS)을 대량으로 발행하였고, 투자은행들이 이를 사들여 합성한 뒤 발행한 채권이 바로 CDO였다. 2007년 주택담보대출 연체율이 높아지면서 이른바 서브프라임 모기지론 사태가 벌어져 채권 가격이 폭락함으로써 주요 금융회사 등 ㅂ 투자자들이 큰 손실을 입고 글로벌 금융위기로 이어지게 되었다.','','ㅂㅊㅂㅇ',ARRAY['CMO']::text[]),
(256,'분리결제','분리결제(Free of Payment)는 증권매매거래 결제시 증권인도와 대금지급이 동시에 이루어지지 않고 개별적으로 이루어지는 방식이다.','분리결제(Free of Payment)는 증권매매거래 결제시 증권인도와 대금지급이 동시에 이루어지지 않고 개별적으로 이루어지는 방식이다. 증권인도와 대금지급이 동시에 이루어지는 동시결제(DVP)방식과 달리 증권인도와 대금지급 간에 시차가 발생하므로 거래당사자일방에게 결제리스크가 발생할 수 있다. 이에 따라 주요국에서는 주로 증권결제기관과 자금결제기관을 연계한 증권대금동시결제방식을 이용하고 있으며 「지급결제 및 시장인프라위원회」(CPMI)와 「국제증권감독기구」(IOSCO)에서 제정한 국제기준인 「금융시장인프라에 관한 원칙」(PFMI)에서도 동시결제방식을 권고하고 있다.','','ㅂㄹㄱㅈ',ARRAY['증권대금동시결제(DVP)']::text[]),
(257,'분산원장기술','분산원장기술(DLT; Distributed Ledger Technology)은 거래정보가 기록된 원장을 특정 기관의 중앙 서버가 아닌 공유(P2P; Peer-to-Peer) 네트워크에 분산하여…','분산원장기술(DLT; Distributed Ledger Technology)은 거래정보가 기록된 원장을 특정 기관의 중앙 서버가 아닌 공유(P2P; Peer-to-Peer) 네트워크에 분산하여 다수의 참가 자가 공동으로 기록·관리하는 기술이다. 전통적 금융시스템의 근간을 이루고 있는 중앙집중형(centralized) 시스템은 원장을 집중·관리하는 ‘제3의 기관’(TTP; Trusted Third Party)을 설립하고 해당 기관에 대한 신뢰를 확보하는 방식으로 발전해 왔다. 예컨대 투자자들이 증권회사를 통해 거래하는 주식을 집중·관리하는 ‘한국예탁결제원’(KSD)이 곧제3의 기관이다. 반면 분산원장기술에서는 다수 참여자가 거래내역이 기록된 원장 전체를 각각 분산 보관(decentralized)하고, 거래할 때마다 이를 검증하며 갱신하는 작업을 공동으로 수행한다. 분산원장기술은 가상자산 발행처럼 누구나 접근 가능하고 거래의 기록 및 관리에도 참여할 수 있는 개방형·비허가형(public, permissionless)과 기업내부또는 금융회사간 시스템처럼 허가받은 경우에만 접근할 수 있는 폐쇄형·허가형(private, permissioned)으로 나눌 수 있다. 분산원장기술은 당초 비트코인·이더리움 등 가상자산 (virtual asset)의 기반 기술로 개발되었으나, 현재는 동 기술을 다양한 금융서비스에 활용하기 위한 방안을 모색중이다.','','ㅂㅅㅇㅈㄱㅅ',ARRAY['P2P대출','블록체인','비트코인','가상자산']::text[]),
(258,'분수효과','분수효과(Trickle-up Effect, Fountain Effect)란 정부가 경제정책으로 저소득층과 중산층의 소득을 먼저 늘려주면 이들의 소비 확대가 생산과 투자로 이어지면서 전체 경제활동이…','분수효과(Trickle-up Effect, Fountain Effect)란 정부가 경제정책으로 저소득층과 중산층의 소득을 먼저 늘려주면 이들의 소비 확대가 생산과 투자로 이어지면서 전체 경제활동이 되살아나고 이로 인해 고소득층의 소득도 늘어날 수 있다는 주장이다. 즉 분수에서 물이 아래에서 위로 솟아나는 것처럼 저소득층에서 시작된 소득과 소비 증대의 효과가 점차상위 계층으로 확산되면서 전체 경제도 좋아질 수 있다는 것이다. 이러한 주장은 영국의 경제학자인 케인즈(J. M. Keynes)가 경제 활성화에 긴요한 총수요 진작을 위해서는 상대적으로 한계소비성향이 높은 저소득층과 중산층에 초점을 맞추어 정부지출을 늘리고 세금을 줄여야 한다는 논리에 근거하고 있다. 이는 분배보다는 성장에, 그리고 저소득층보다는 고소득층에 중점을 두어 경제정책을 운용해야 한다는 낙수효과와는 상반되는 개념이다. ㅂ','','ㅂㅅㅎㄱ',ARRAY['글로벌가치사슬(GVC)']::text[]),
(259,'불완전경쟁시장','시장에 의한 가격결정에 어떠한 영향도 미칠 수 없는 상태를 완전경쟁이라 한다.','시장에 의한 가격결정에 어떠한 영향도 미칠 수 없는 상태를 완전경쟁이라 한다. 이는 경제주체의 자유로운 시장 진입과 퇴출, 다수의 공급자와 수요자 존재, 거래되는 재화 및 서 비스의 동질성, 정보의 완전성이 충족되는 경우에만 존재 가능하다. 현실에서는 이러한 요건이 충족되기 어려워 독점시장, 과점시장과 독점적 경쟁시장과 같은 형태의 불완전경쟁시장이 나타나게 된다. 하나의 공급자가 존재하여 재화 및 서비스의 가격을 결정하는 시장을 독점시장이라고 한다. 두 개 이상의 소수 공급자만이 서로 경쟁하는 시장을 과점시장이라고 하는데, 이러한 예로는 국내의 이동통신서비스, 자동차 시장 등을 들 수 있다. 마지막으로 독점적 경쟁시장에서는 다수의 공급자가 각기 특화된 재화 및 서비스를 생산함으로써 독자적으로 가격을 결정할 수 있는 시장지배력을 행사할 수 있다.','','ㅂㅇㅈㄱㅈㅅㅈ',ARRAY['독점/과점','자연독점']::text[]),
(260,'불태화정책','수출입 거래나 국경 간 자본유출입 거래는 국내은행을 통해 국내통화로 전환되며 이에 따라 국내통화량이 변동하게 된다.','수출입 거래나 국경 간 자본유출입 거래는 국내은행을 통해 국내통화로 전환되며 이에 따라 국내통화량이 변동하게 된다. 이러한 통화량의 변동은 금리와 물가에 영향을 미칠 가 능성이 있다. 불태화정책(Sterilization Policy)이란 이처럼 해외부문으로부터의 외화유입으로 인해 본원통화가 증가하고 그 결과로 금리나 물가가 중앙은행이 목표한 바와 다르게 변동할 우려가 발생할 경우, 중앙은행이 공개시장 조작이나 지급준비율 조정 등을 통해 본원통화의 증가를 상쇄시키는 정책을 말한다. 따라서 불태화정책의 수단은 일반 통화정책과 같지만 그 목적이 해외부문에서 비롯된 통화량 증가를 억제하기 위한 것이란 점에 서 다르다. 불태화정책은 중앙은행 등의 외환시장 개입과 연관되어 이루어지는 경우도 있다. 중앙은행이 환율 안정을 위해 외환시장에서 외환을 매입할 경우 그 반대급부로 원화대금이 거래상대방에 지급되고 이에 따라 국내 통화량이 증가하게 되는데, 이 경우 중앙은행은 공개시장조작 등을 통해 증가분을 회수(불태화)함으로써 통화량을 개입 전 수준으로 유지할 수 있다.','','ㅂㅌㅎㅈㅊ',ARRAY['외환시장','스무딩오퍼레이션']::text[]),
(261,'브레튼우즈체제','브레튼우즈체제는 1944년 7월 미국의 뉴햄프셔주 브레튼우즈에서 44개 연합국 대표들이 새로운 국제통화제도 구축을 위해 체결한 협정에 따라 발족한 국제통화체제를 말한다.','브레튼우즈체제는 1944년 7월 미국의 뉴햄프셔주 브레튼우즈에서 44개 연합국 대표들이 새로운 국제통화제도 구축을 위해 체결한 협정에 따라 발족한 국제통화체제를 말한다. 이 협정을 체결하게 된 배경은 1930년대 대공황의 여파로 인한 금본위제도 붕괴, 무역','','ㅂㄹㅌㅇㅈㅊㅈ','{}'::text[]),
(262,'브렉시트(Brexit)','규제 확대, 환율 불안정에 이어 1940년대 국제유동성 부족, 외환규제 확산 등으로 국제통화질서가 위기에 직면하게 되었기 때문이다.','규제 확대, 환율 불안정에 이어 1940년대 국제유동성 부족, 외환규제 확산 등으로 국제통화질서가 위기에 직면하게 되었기 때문이다. 브레튼우즈체제는 국제통화제도의 본질적인 기능인 유동성 공급과 국제수지 조정 메커니즘을 미달러화를 기축통화로 하는 금환본위제도와 조정가능 고정환율제도를 통해서 해결하고자 하였다. 즉 각국은 달러를 대외준비자산으로 보유하고 미국은 다른 나라가 보유한 달러에 대해 금태환을 보장하며, 각국의 고정환율에 조정이 필요한 경우 국제통화기금(IMF)과 협의하여 변경할 수 있도록 하였다. 이를 뒷받침하기 위하여 설립된 국제기구가 IMF와 국제부흥개발은행(IBRD)이다. 1960년대 들어 국제유동성 수준이 미국의 국제수지 상태에 따라 결정되고 환율 변경을 통한 불균형 개선이 쉽지 않은 등의 구조적인 문제가 대두되는 가운데 1971년 미국이 달러화의 금태환을 정지하고 뒤이어 선진국들이 변동환율제도로 이행함에 따라 브레튼우즈체제는 사실상 붕괴되었다. ㅂ','','ㅂㄹㅅㅌ()',ARRAY['유럽연합(EU)']::text[]),
(263,'브릭스(BRICS)','브릭스(BRICS)는 브라질(Brazil), 러시아(Russia), 인도(India), 중국(China), 남아프리카공화국(South Africa) 등 5개국의 영문 앞 글자를 따서 만든 용어다.','브릭스(BRICS)는 브라질(Brazil), 러시아(Russia), 인도(India), 중국(China), 남아프리카공화국(South Africa) 등 5개국의 영문 앞 글자를 따서 만든 용어다. 2001년 골드만 삭스의 짐 오닐이 잠재 경제력이 높은 브라질(Brazil), 러시아(Russia), 인도(India), 중국 (China) 등 4개국을 지칭하기 위해 BRICs라는 용어를 처음 사용하였다. 이들 4개국은 2006년부터 비공식적인 외무장관회의를 시작한 데 이어 2009년 첫 번째 정상회의를 개최한 이후 지속적으로 모임을 갖고 있다. 2011년 남아프리카공화국이 포함되면서 이들을 가리키는 용어가 기존의 BRICs에서 BRICS로 바뀌었으며 이에 따라 브릭스의 지정학적대표성이 부각되는 한편 이들 5개국 간 대화의 깊이와 폭도 더욱 넓혀왔다. 2024년 1월이집트, 에디오피아, 이란 아랍에미레이트가, 2025년 1월에는 인도네시아가 정식 회원국으로 가입하였다. 브릭스는 현재의 경제성장 속도와 앞으로의 발전 전망에 비추어 신흥경제대국으로 발돋움할 가능성이 높은 나라들을 하나의 경제권으로 묶은 대표적인 블록으로 자리잡아 가고 있다. 실제로도 브릭스 국가들은 공통적으로 거대한 영토와 노동력, 풍부한 지하자원 등 경제대국으로 성장할 수 있는 잠재력을 갖춘 것으로 평가되고 있다.','','ㅂㄹㅅ()','{}'::text[]),
(264,'브릿지론','개인이나 기업이 주택구입, 대규모 개발 프로젝트 수행 등을 위해 장기 자금조달이 필요 할 경우, 해당 자금 마련 이전에 일시적으로 소요되는 비용을 충당하기 위해 단기 자금조달 수단으로 이용하는…','개인이나 기업이 주택구입, 대규모 개발 프로젝트 수행 등을 위해 장기 자금조달이 필요 할 경우, 해당 자금 마련 이전에 일시적으로 소요되는 비용을 충당하기 위해 단기 자금조달 수단으로 이용하는 것이 브릿지론이다. 마치 다리(bridge) 역할을 하는 자금조달 수단이다. 예를 들어 부동산 개발 사업을 실시할 경우 토지를 매입하는 초기 단계에서 이에 필요한 자금을 본격적인 PF(Project Financing) 대출로 전환되기 이전에 일시적으로 조달하는 용도로 사용된다. 브릿지론은 일반적으로 6개월에서 1년 만기 정도의 단기대출이며 본 PF대출에 비해 금리가 높다. 이는 초기 사업비용 충당이 주목적인 브릿지론의 특성을 감안할 때 리스크가 높은 점이 반영된 것이다.','','ㅂㄹㅈㄹ','{}'::text[]),
(265,'비관측경제(NOE)','기록하여 ② 모든 구성원들에게 전송하고 ③ 블록의 유효성이 확보될 경우 새 블록을 ④ 기존의 블록에 추가 연결(chain)하여 보관하는 방식의 알고리즘이다.','기록하여 ② 모든 구성원들에게 전송하고 ③ 블록의 유효성이 확보될 경우 새 블록을 ④ 기존의 블록에 추가 연결(chain)하여 보관하는 방식의 알고리즘이다. 각 블록은 이전 블록에 대한 연결자인 해시포인터(a hash pointer, 위변조 점검 수단), 시간표시 및 거래데이 터를 포함한다. 블록체인은 효율적이고 검증 가능한 방식으로 거래를 기록할 수 있는 개방된 분산원장 즉, 데이터베이스 역할을 한다. 이는 참여자간 공유(peer-to-peer) 네트워크가 집단적으로 새 블록을 검증하는 프로토콜에 따라 관리된다. 그래서 만약 누군가 거래기록을 조작하려면 참여자간 연결된 모든 블록을 새 블록 생성 이전에 조작해야한다. 즉 일정 시간 안에 수많은 블록을 모두 조작해야 하는데, 이는 사실상 불가능하므로 보안성이 높은 것이다. 이 블록체인 덕분에 새로운 단위 가치의 거래가 오직 한 번만 이뤄짐으로써, 이중 지급(double spending) 같은 문제를 해결할 수 있게 되었다. 또한 블록체인에서는 ‘제3의 기관’이 필요 없는 탈중앙화와 중개 기관을 거치지 않는 탈중개화가 이뤄지기 때문 ㅂ 에 거래비용이 획기적으로 낮아진다. 그래서 블록체인은 비트코인·이더리움(Ethereum) 등 가상자산 운용의 기반이 될 뿐만 아니라 스마트계약, 증권 발행 및 거래, 해외송금 및자금이체, 무역금융, 부동산 등기, 고가품(예: 다이아몬드)의 정품 인증, 디지털 ID 관리, 전자투표, 개인건강기록 관리 등 여러 분야에서 무한한 혁신 잠재력을 지니고 있다.','','ㅂㄱㅊㄱㅈ()',ARRAY['국내총생산(GDP)']::text[]),
(266,'비교우위','특정 국가나 경제주체가 다른 국가나 경제주체에 비해 상대적으로 더 적은 기회비용으로 어떤 재화나 서비스를 생산할 수 있는 능력을 말한다.','특정 국가나 경제주체가 다른 국가나 경제주체에 비해 상대적으로 더 적은 기회비용으로 어떤 재화나 서비스를 생산할 수 있는 능력을 말한다. 각국이 비교우위를 가진 상품 생산에 특화하고 이를 교역함으로써 상호 이익을 극대화할 수 있다는 논리로 국가간 무역 발생 이유를 설명하고 있다. 고전학파 경제학자인 리카르도(D. Ricardo)가 제시한 이론으로 자유무역이 교역 대상국 모두에게 유리하다는 국제 분업 및 무역에 관한 이론적 기반을 제공하였다. 그러나 노동가치설에 근거하여 노동투입에 따른 요소비용만을 고려하였고 두 나라 간에 두 가지 재화 생산만이 가능하다는 제한적인 가정에 근거하고 있다. 오늘날에는 상품의 종류가 세분되고 또한 같은 품질과 특성을 지닌 상품이 다수 생산되고 있어 생산비용의 상대적 차이만으로 무역의 발생 원인을 설명하는 데는 한계가 있다. 한편, 보다 먼저 애덤 스미스(Adam Smith)는 생산성의 절대적 차이에 근거한 국제분업과 무역의 절대우위이론을 주장하였다.','','ㅂㄱㅇㅇ',ARRAY['현시비교우위지수(RCA)']::text[]),
(267,'비용인상 인플레이션','재화나 서비스의 생산과 관련하여 투입요소 비용의 상승에 의해 물가가 지속적으로 오르게 되는 것을 비용인상 인플레이션(Cost-Push Inflation)이라고 한다.','재화나 서비스의 생산과 관련하여 투입요소 비용의 상승에 의해 물가가 지속적으로 오르게 되는 것을 비용인상 인플레이션(Cost-Push Inflation)이라고 한다. 주요 투입요소인 노동, 자본, 원자재 등의 가격이 상승하면 기업은 증가한 생산비용을 가격에 반영시키므로 최종재의 가격이 오르게 되는 것이다. 비용인상 인플레이션은 경제 내의 생산활동을 위축시키면서 유발되므로 사람들의 소득 수준이 악화될 가능성이 크다. 실제로 1970 년대 발생한 2차례의 오일쇼크(석유가격이 급등하여 재화 및 서비스의 생산비가 크게','','ㅂㅇㅇㅅㅇㅍㄹㅇㅅ','{}'::text[]),
(268,'비트코인','상승했음)로 인해 유발된 비용인상 인플레이션은 이러한 가능성을 보여주고 있다.','상승했음)로 인해 유발된 비용인상 인플레이션은 이러한 가능성을 보여주고 있다. 당시유가 상승으로 인해 생산비가 증가하면서 생산활동이 위축되고 이로 인해 경기가 둔화되었다.','','ㅂㅌㅋㅇ',ARRAY['가상자산','작업증명','블록체인']::text[]),
(269,'빅데이터','빅데이터(Big Data)란 복잡하고 다양한 대규모 데이터세트 자체는 물론 이 데이터세트로 부터 정보를 추출하고 결과를 분석하여 더 큰 가치를 창출하는 기술을 뜻한다.','빅데이터(Big Data)란 복잡하고 다양한 대규모 데이터세트 자체는 물론 이 데이터세트로 부터 정보를 추출하고 결과를 분석하여 더 큰 가치를 창출하는 기술을 뜻한다. 수치 데이 터 등 기존의 정형화된 정보뿐 아니라 텍스트·이미지·오디오·로그기록 등 여러 형태의 비정형 정보가 데이터로 활용된다. 최근 모바일 기기와 SNS 이용 보편화, 사물인터넷 확산등으로 데이터의 양이 기하급수적으로 늘어나고 있다. 하지만 저장매체의 가격 하락 등 으로 데이터 관리비용이 감소하고, 클라우드 컴퓨팅 등으로 데이터 처리·분석 기술도 발전하면서 빅데이터 활용 여건은 계속 개선되어가고 있다. 빅데이터 관련 기술은 데이터를 수집·저장하는 데이터 ‘처리기술’과 데이터를 분석·시각화하는 데이터 ‘분석기술’로 구성된다. 데이터 처리기술의 발달은 저가의 서버와 하드디스크를 여러 대 연결하여 대용량데이터를 분산 처리함으로써 기존의 고비용 데이터 분석 솔루션을 대체하였다. 데이터 분석기술의 발달은 기존 데이터 분석에서는 불가능했던 비선형적 상관관계 규명, 감성분석등 비정형화된 분석도 가능하게 만들었다. 여기서 감성분석은 텍스트 채굴(text mining) 기술의 하나로 텍스트(예: 상품 품평)에 나타난 사람들의 태도·의견·성향 등 주관적인 속성을 지닌 데이터 추출·분석기법이다. 이처럼 빅데이터는 대량(high-volume), 초고속 (high-velocity), 고다양성(high-variety), 고가변성(high-variability)의 특성을 지니며 고정확성(high-veracity)을 확보해야 하는 정보 자산이다.','','ㅂㄷㅇㅌ',ARRAY['로보어드바이저']::text[]),
(270,'빅맥지수','빅맥지수(Big Mac Index)는 각국 통화의 구매력 정도 또는 환율 수준을 측정하기 위해일물일가의 법칙을 햄버거 가격에 적용한 것으로 영국에서 발행되는 주간 경제전문지 이 코노미스트지(The…','빅맥지수(Big Mac Index)는 각국 통화의 구매력 정도 또는 환율 수준을 측정하기 위해일물일가의 법칙을 햄버거 가격에 적용한 것으로 영국에서 발행되는 주간 경제전문지 이 코노미스트지(The Economist)에서 1986년 이래 매년 전 세계적으로 판매되고 있는 맥도날드의 빅맥 가격을 비교·분석해서 발표하고 있다. 맥도날도의 빅맥은 전 세계 120개국에서 동일한 재화로 판매되고 있으므로, 이 빅맥지수를 이용하여 일물일가의 법칙 또는 절대적 구매력평가를 간단하게 검증할 수 있는 기회를 독자들에게 제공한다는 취지이 다. 만약 일물일가의 법칙이 완전하게 성립한다면 세계 모든 나라에서 빅맥의 미달러화','','ㅂㅁㅈㅅ','{}'::text[]),
(271,'빈일자리율','가격이 동일하여야 하므로 실제 환율과는 다른 구매력평가환율을 산정해 볼 수 있다.','가격이 동일하여야 하므로 실제 환율과는 다른 구매력평가환율을 산정해 볼 수 있다. 예를 들어 어느 기준시점의 우리나라 빅맥 가격이 5,500원이고 미국에서의 가격은 5.69달러라 하면, 구매력평가이론의 일물일가의 법칙이 성립한다면 원/달러 환율은 967원/달러(=5,500원/5.69달러)가 되어야 한다. 그런데 그 시점의 실제 환율이 1,350원/달러라면빅맥지수로 볼 때 원화는 미달러화 대비 약 28% 저평가되어 있다고 볼 수 있다.','','ㅂㅇㅈㄹㅇ',ARRAY['베버리지 곡선']::text[]),
(272,'사이드카','사이드카는 주식시장에서 선물 가격 급등락으로 인한 현물 시장의 과도한 변동을 막기 위해 프로그램 매매 호가의 효력을 일시적으로 정지시키는 시장 안정화 장치이다.','사이드카는 주식시장에서 선물 가격 급등락으로 인한 현물 시장의 과도한 변동을 막기 위해 프로그램 매매 호가의 효력을 일시적으로 정지시키는 시장 안정화 장치이다. 코스피200 선물 가격이 전일 종가 대비 5%(코스닥150의 경우 6%) 이상 변동(상승 또는 하락)한 시세가 1분 이상 지속될 경우 발동되며, 프로그램 매매 호가의 효력이 5분간 정지된다. 사이드카는 프로그램 매매만을 하루 한 차례에 한해 일시적으로 중지시키고 발동 5분 후 자동으로 해제되며, 주식시장 매매거래 종료 40분 전 이후에는 발동하지 않는 특징이 있다. 사이 드카는 증권시장의 공습경보로 여겨지는 ‘서킷브레이커(Circuit Breaker)’의 전 단계로, 투자자에게 합리적인 판단을 할 수 있는 시간적 여유를 주기 위한 경계경보라 할 수 있다.','','ㅅㅇㄷㅋ',ARRAY['서킷브레이커']::text[]),
(273,'사이버리스크','정보통신기술의 발달로 기업경영활동에서 디지털화가 가속화되고 상호 연결이 확대되어감에 따라 전자상거래나 정보통신기술을 이용하여 이루어지는 활동 중 사이버 상에서 발생하는 예기치 못한 사고로 인해…','정보통신기술의 발달로 기업경영활동에서 디지털화가 가속화되고 상호 연결이 확대되어감에 따라 전자상거래나 정보통신기술을 이용하여 이루어지는 활동 중 사이버 상에서 발생하는 예기치 못한 사고로 인해 기업이 부담하게 될 유·무형의 비용이 증가하는 위험을','','ㅅㅇㅂㄹㅅㅋ','{}'::text[]),
(274,'사전적 정책방향 제시 (Forward Guidance)','말한다.','말한다. 사이버리스크 발생에 따른 유형의 비용에는 자금 분실, 컴퓨터시스템 손상 또는 악성코드 감염, 네트워크 폐쇄에 따른 조업중단, 고객정보 및 디지털자산의 분실, 정보유출에 따른 법적 및 피해자 보상 등이 있으며, 무형의 비용으로는 고객 이탈, 기업 신뢰도 하락, 브랜드 이미지 손상, 핵심기술 유출에 따른 경쟁우위 훼손 등이 있다. 사이버리스크에 대한 대책으로는 사전 대응(secure)과 지속적 경계(vigilant) 및 신속한 복구능력 (resilient) 확보가 제시되고 있다. 한편 디지털 정보량의 증대와 클라우드 컴퓨팅 이용 기업의 증가세를 감안할 때 향후 사이버리스크에 대한 노출은 더욱 늘어날 것으로 예상된다. 사전담보제사전담보제(Collateral Requirements)는 지급결제시스템의 참가자로 하여금 여타 시스템 참가자들 모두에 대한 순채무를 결제하기에 충분한 담보를 사전에 제공토록 하여 결제불이행이 실제로 발생하였을 때 결제불이행 기관의 담보를 처분하여 결제의 종료를 보장하는 제도다. 이는 참가기관간 순채무액만을 지정시점에 결제하는 이연차액결제시스템에 서 일부 기관의 결제불이행이 타 기관의 연쇄적인 결제불이행으로 이어지지 않도록 하는 리스크 관리기법의 하나이다. 예치 담보로는 중앙은행 예치금이나 국채 등 유동성이 높은 증권이 주로 이용되고 있다. 만약 각 참가기관이 자신의 순채무한도 전액에 해당하는 담보를 예치한다면 차액결제시스템은 결제불이행 기관의 수에 관계없이 나머지 참가기관에 어떠한 손실도 주지 않고 결제를 종료시킬 수 있다. 우리나라의 경우에도 차액결제시스템에 참가하는 금융기관은 국채, 정부보증채, 통화안정증권 등을 차액결제 이행을 위한 담보로 제공하도록 되어 있다.','','ㅅㅈㅈㅈㅊㅂㅎㅈㅅ()',ARRAY['양적완화정책','제로금리정책','통화정책 커뮤니케이션']::text[]),
(275,'사회보장제도','사회보장제도는 개인이 어떠한 불행을 당하더라도 국가가 최소한의 인간다운 생활을 보장할 수 있도록 하는 제도이다.','사회보장제도는 개인이 어떠한 불행을 당하더라도 국가가 최소한의 인간다운 생활을 보장할 수 있도록 하는 제도이다. 사회 불평등 현상을 해결하기 위해 도입된 것으로 사회보험과 공공부조, 사회복지서비스가 대표적이다. 사회보험(社會保險)은 산업재해, 실업, 질병 등으로 인하여 소득이 상실되었을 때를 대비한 보험으로 산업재해보험, 국민연금, 고 용보험, 건강보험이 있다. 보험료는 일반적으로 혜택을 받는 개인과 고용주 또는 국가가 나누어 부담하며, 소득이 높을수록 부담이 높아진다. 한편 공공부조(公共扶助)는 비용 전부를 국가가 부담하며 생활능력이 없는 사람의 최저한의 생활보호를 위해 마련된 제도로 ㅅ 기초생활보장제도가 대표적인 예이다. 마지막으로 사회복지서비스는 도움을 필요로 하는 모든 국민이 정상적인 생활을 할 수 있도록 도와주는 상담, 재활, 직업소개 및 지도 등 여러 지원제도를 의미한다. 주로 아동, 노인, 장애인을 위한 복지제도가 여기에 포함된다.','','ㅅㅎㅂㅈㅈㄷ',ARRAY['사회보험','상대적 빈곤율']::text[]),
(276,'사회보험','사회보험(Social Insurance)이란 보험방식을 통해 발생 가능한 각종 사회적 위험에 대처함으로써 국민의 생활, 건강, 소득 등을 보장하는 제도를 가리킨다.','사회보험(Social Insurance)이란 보험방식을 통해 발생 가능한 각종 사회적 위험에 대처함으로써 국민의 생활, 건강, 소득 등을 보장하는 제도를 가리킨다. 구체적으로는 ① 산업재해보험(업무상 재해를 입었을 경우 신속한 보상 및 복귀 지원) ② 건강보험(질병, 상해, 사망 등의 사고가 발생할 경우 의료서비스 제공) ③ 국민연금(퇴직, 노령, 사망 등에 따른당사자 및 유족의 생활보장) ④ 고용보험(실직자의 생활 안정 및 재취업 지원)으로 구분된 다. 이들 제도는 사회보장정책을 수행하기 위한 주요 수단으로 활용되며 특히 노동자와 그 가족을 발생 가능한 각종 위험으로부터 보호하는 것을 목적으로 한다. 사회보험은 반드시 개인의 자유의사에 의하여 가입하는 것은 아니며 보험료는 국가, 기업 및 개인이 분담하되 개인이 받을 위험 정도가 아닌 소득 수준에 비례하여 산정된다.','','ㅅㅎㅂㅎ',ARRAY['사회보장제도']::text[]),
(277,'산업연관표(I/O Tables)','일정 기간(보통 1년) 동안 국민경제 내에서 발생하는 재화와 서비스의 생산 및 처분과 관련된 모든 거래 내역을 일정한 원칙과 형식에 따라 기록한 종합적인 통계표이다.','일정 기간(보통 1년) 동안 국민경제 내에서 발생하는 재화와 서비스의 생산 및 처분과 관련된 모든 거래 내역을 일정한 원칙과 형식에 따라 기록한 종합적인 통계표이다. 세로 방향은 각 산업에서 생산활동을 위해 사용한 중간재, 노동, 자본 등 생산요소의 내역을 나타내는 투입 구조를, 가로방향은 각 산업에서 생산된 산출물의 처분내역을 나타내는 배분구조를 의미한다. 이 표를 통해 산업 간에 그물같이 복잡하게 얽혀 있는 상호연관관계를 파악할 수 있다. 산업연관표는 1930년대 초 레온티에프(W. Leontief) 교수가 처음으로 작성 발표한 이래 선진국은 물론 개발도상국에 이르기까지 많은 나라에서 작성되고 있다. 산업연관표는 경제구조 및 정책효과 분석에 많이 이용되고 있으며 국가 간 산업연관관계나 지역경제 분석 및 환경, 에너지 분야 등에까지 다양하게 활용되고 있다. 우리나라에서 는 한국은행이 「1960년 산업연관표」를 처음 작성한 이후 매 5년마다(끝이 0과 5인 연도) 실측표를 작성하였으며 2006년부터는 매년 산업연관표를 작성하여 공표하고 있다.','','ㅅㅇㅇㄱㅍ(/)',ARRAY['고용유발효과/취업유발효과','생산유발효과']::text[]),
(278,'삼불원칙','삼불원칙(Impossible Trinity, Trilemma)는 ① 고정환율 유지 ② 자본의 자유로운 이동 ③ 통화정책의 독립성 등 세 가지 정책목표를 동시에 만족시키는 것은 불가능함을 의미한 다.','삼불원칙(Impossible Trinity, Trilemma)는 ① 고정환율 유지 ② 자본의 자유로운 이동 ③ 통화정책의 독립성 등 세 가지 정책목표를 동시에 만족시키는 것은 불가능함을 의미한 다. 고정환율제도하에서는 환율을 고정함으로써 환율 변동에 따른 충격을 완화하고 일정부분 거시경제정책의 자율성을 확보할 수 있으나 이를 위해서는 자본이동을 제약할 수밖에 없다. 반대로 자유변동환율제도하에서는 자본이 자유롭게 이동하므로 외화유동성 확보가 용이하고, 외부 충격이 환율 변동을 통해 흡수되어 거시경제정책을 자율적으로 수행하기 쉽다는 장점이 있으나 이를 위해서는 환율 변동을 용인할 수밖에 없다. 이 밖에 통화위원회제도의 경우 국내통화를 미달러화 등에 일정 비율로 고정함으로써 환율 변동은 제한할 수 있으나 외화 공급에 비례하여 국내통화가 자동적으로 공급되어야 하므로 통화정책의 자율성은 크게 제약을 받을 수밖에 없다.','','ㅅㅂㅇㅊ',ARRAY['고정환율제도/자유변동환율제도']::text[]),
(279,'상계관세','상계관세(Countervailing Duties)는 수출국이 수출기업에 보조금이나 장려금을 지급하여지나치게 낮은 가격을 책정할 경우 수입국이 이로 인한 경쟁력 저하를 상쇄하기 위해 부과 하는…','상계관세(Countervailing Duties)는 수출국이 수출기업에 보조금이나 장려금을 지급하여지나치게 낮은 가격을 책정할 경우 수입국이 이로 인한 경쟁력 저하를 상쇄하기 위해 부과 하는 관세를 말한다. 즉 수출국 정부의 보조를 받아 가격·품질 면에서 우위를 갖게 된 수입품으로 인해 수입국이 피해를 입거나 피해를 입을 우려가 있는 경우 그 효과를 상쇄할 목적으로 정규관세 이외에 부과하게 된다. 이러한 점에서 상계관세는 수입국 산업의 경쟁력을 유지하기 위한 일종의 차별관세라 할 수 있다. 우리나라에서는 관세법 제57조에 국내산업을 보호할 필요가 있다고 인정되는 경우 상계관세를 부과할 수 있다고 규정하고 있다.','','ㅅㄱㄱㅅ',ARRAY['지니계수','사회보장제도']::text[]),
(280,'상장지수펀드(ETF)','주식, 채권, 통화, 원자재 등의 가격지수를 추종하는 것이 목표인 인덱스펀드의 지분을 거래소에 상장하여 일반주식처럼 거래하도록 한 금융상품이다.','주식, 채권, 통화, 원자재 등의 가격지수를 추종하는 것이 목표인 인덱스펀드의 지분을 거래소에 상장하여 일반주식처럼 거래하도록 한 금융상품이다. 최초의 ETF(Exchange Traded Fund)는 S&P500지수 펀드로 1993년 1월에 뉴욕증권거래소에서 매매되기 시작하였고, 국내에서는 2002년 10월 KOSPI 200을 추종하는 KODEX 200과 KOSEF 200 ETF의 매매가 개시되었다. 국내에서 ETF는 설정을 원하는 기관투자자가 지정참가회사(증권사)를 통해 설정에 필요한 주식바스켓을 집합투자업자(자산운용사)에 납입함으로써 발행된다. 이렇게 발행된 ETF가 거래소에 상장되면 일반주식과 동일한 방식으로 거래된다. 유통시장에서는 지정참가회사 중 1개사 이상이 유동성공급자로 지정되어 ETF의 원활한 거래를 돕는다. ETF는 통상적인 펀드와 달리 개인 주식거래계좌를 통해 손쉽게 거래할 수있는 데다 증권거래세 면제 등으로 거래비용이 낮고 소액으로도 분산투자가 가능하다는 장점을 가지고 있다. 우리나라의 ETF는 처음에는 국내 주가지수를 추종하는 상품이 대부분이었으나 현재는 국내외 주식 및 채권, 파생상품, 통화, 원자재 등의 가격지수를 활용한 상품으로 영역이 넓어졌다. 또한 수익률이 지수의 일정배율에 연동되는 레버리지 ETF, 지수변동의 반대방향으로 수익률이 정해지는 Inverse ETF 등 다양한 구조의 상품들이 있다.','','ㅅㅈㅈㅅㅍㄷ()','{}'::text[]),
(281,'상품공동기금(CFC)','1989년 7월 설립된 상품공동기금(CFC; Common Fund for Commodities)은 1차산품의 수급 안정을 위한 국제협력 증진과 국제상품협정 체결 촉진 및 기능 활성화를 목적으로…','1989년 7월 설립된 상품공동기금(CFC; Common Fund for Commodities)은 1차산품의 수급 안정을 위한 국제협력 증진과 국제상품협정 체결 촉진 및 기능 활성화를 목적으로 하고 있다. 주요 기능으로는 국제상품협정에 따른 완충재고 유지를 위한 금융지원, 상호관세 1차산품의 개발 촉진 및 교역조건 개선을 위한 연구개발 지원, 1차산품에 관한 가맹국 간정보교환 및 정책협의 촉진 등을 들 수 있다. 2021년 말 기준 가맹국은 101개국과 9개 기구(EC, AU, COMESA 등)로 납입자본금은 139.5백만 달러(약정액 기준)이며 출연금은 175.4백만 달러이다. 우리나라는 1989년 7월 설립과 함께 가입하였으며 2021년 말 기준 1,051.8천 달러를 출자하였다.','','ㅅㅍㄱㄷㄱㄱ()',ARRAY['세계무역기구(WTO)']::text[]),
(282,'상품수지','거주자와 비거주자 간의 상품 수출입 거래를 계상한 것으로, 경상수지의 한 부분이다.','거주자와 비거주자 간의 상품 수출입 거래를 계상한 것으로, 경상수지의 한 부분이다. 수출이 수입보다 많으면 흑자, 수출보다 수입이 많으면 적자로 표시한다. 상품수지의 수출입은 관세청에서 통관기준으로 작성하는 무역수지의 수출입과 일치하지 않는 경우가 많 ㅅ 다. 이는 관세청에서는 상품이 우리나라의 관세선을 통과하면 수출입으로 계상하는 반면, 국제수지의 상품수지에서는 상품의 소유권이 이전되어야 수출입으로 간주하는 소유권이 전(change of ownership) 기준을 따르기 때문이다. 또한 무역수지에서 수출은 FOB가 격, 수입은 운임 및 보험이 포함되어 있는 CIF가격으로 평가하지만, 상품수지에서는 수출과 수입 모두 FOB가격으로 평가한다는 차이점도 있다.','','ㅅㅍㅅㅈ',ARRAY['경상수지']::text[]),
(283,'상호관세','상호관세(Reciprocal Tariff)는 특정 상대국이 자국 제품에 대해 과도하거나 불공정한 관세를 부과할 경우 이에 대해 동일하거나 유사한 방식으로 관세를 부과하는 경우를 말한 다.','상호관세(Reciprocal Tariff)는 특정 상대국이 자국 제품에 대해 과도하거나 불공정한 관세를 부과할 경우 이에 대해 동일하거나 유사한 방식으로 관세를 부과하는 경우를 말한 다. 보복관세(retaliatory tariff)라고 불리기도 한다. 이는 무역불균형을 시정하기 위한 노력의 일환으로 해석될 수 있지만 주는 만큼 받는 방식이기 때문에 무역분쟁이 더 심화될우려가 있다. 1930년대 대공황 시기에 관세를 점차 낮추기 위한 방식으로 등장했지만 최근 미국 트럼프 행정부가 무역장벽을 높이는 수단으로 활용하여 다시 주목을 받고 있다.','','ㅅㅎㄱㅅ',ARRAY['보편관세']::text[]),
(284,'생산세','현재 국민계정 작성기준인 국민계정체계(SNA)에서는 조세를 크게 종전 간접세에 해당하는 생산세(Taxes on Production)와 소득·부 등에 대한 경상세, 자본세로 분류하고 있다.','현재 국민계정 작성기준인 국민계정체계(SNA)에서는 조세를 크게 종전 간접세에 해당하는 생산세(Taxes on Production)와 소득·부 등에 대한 경상세, 자본세로 분류하고 있다. 생산세는 생산물세(taxes on products)와 기타생산세(other taxes on products)로 분류되는데, 생산물세는 생산자가 재화 및 서비스를 생산, 배달, 판매, 이전 또는 기타 용도 로 사용하였을 때 동 재화 및 서비스에 대해 부과되는 조세를 말한다. 생산물세에는 재화의 수입이나 비거주자의 거주자에 대한 서비스 공급 등에 부과되는 수입세 및 관세가 포함된다. 한편, 기타생산세는 기업이 생산에 참여한 결과 부과되는 조세 중 생산물세를 제외한 모든 조세를 말한다. 여기에는 주로 생산에 이용된 토지, 고정자산, 노동 또는 특정거래나 활동에 대한 조세가 포함된다.','','ㅅㅅㅅ','{}'::text[]),
(285,'생산유발효과','한 나라에서 각 산업의 생산활동은 소비, 투자, 수출 등 최종수요의 크기에 따라 결정되는 데, 최종수요의 변화가 생산에 미치는 영향을 생산유발효과라 한다.','한 나라에서 각 산업의 생산활동은 소비, 투자, 수출 등 최종수요의 크기에 따라 결정되는 데, 최종수요의 변화가 생산에 미치는 영향을 생산유발효과라 한다. 예를 들어, 자동차 수출이 1대 증가할 경우 엔진, 타이어와 같은 수많은 중간재가 생산되어야 하고 다시 이들중간재의 생산을 위해서 냉간압연강재 같은 철강제품, 고무, 타이어코드 등 다른 원료의 생산이 필요하게 된다. 이와 같이 자동차의 생산은 아무 관련이 없는 것처럼 보이는 많은 산업에까지 영향을 주게 되는데 이러한 생산유발효과는 산업 간의 수급균형이 이루어질때까지 무한히 계속된다. 생산유발효과는 생산유발계수의 크기로 측정할 수 있는데, 생산유발계수는 최종수요가 한 단위 발생하였을 때 이를 충족시키기 위하여 각 산업부문에서 직·간접적으로 유발되는 생산액의 수준을 의미하는 것으로 생산유발계수가 클수록 국내생산에 미치는 영향이 크다고 해석할 수 있다. 생산유발계수를 이용하여 소비, 투자, 수출등 최종수요의 변동이 국내 각 산업의 산출, 부가가치, 고용 등 생산활동에 미치는 파급효과를 계량적으로 분석할 수 있다.','','ㅅㅅㅇㅂㅎㄱ',ARRAY['고용유발효과/취업유발효과']::text[]),
(286,'생산자물가지수(PPI)','국내생산자가 국내시장에 공급하는 상품과 서비스의 평균적인 가격변동을 측정하기 위하여 작성되는 물가지수로서 그 대상품목의 포괄범위가 넓어 전반적인 상품과 서비스의 수급 동향이 반영된 일반적인…','국내생산자가 국내시장에 공급하는 상품과 서비스의 평균적인 가격변동을 측정하기 위하여 작성되는 물가지수로서 그 대상품목의 포괄범위가 넓어 전반적인 상품과 서비스의 수급 동향이 반영된 일반적인 물가수준의 변동을 측정할 수 있기 때문에 일반목적지수로서 의 성격을 갖는다. 지수작성에 이용되는 가격은 생산자가 제품 한 단위당 실제로 수취하는 기초가격(basic price)이다. 생산자물가지수는 1910년부터 한국은행에서 작성해 오고 있다.','','ㅅㅅㅈㅁㄱㅈㅅ()',ARRAY['소비자물가지수(CPI)','기초가격']::text[]),
(287,'생산자제품재고지수','현실 경제에서는 경기의 좋고 나쁨에 따라 재고의 증가 또는 감소 현상이 필연적으로 나 타나게 마련이다.','현실 경제에서는 경기의 좋고 나쁨에 따라 재고의 증가 또는 감소 현상이 필연적으로 나 타나게 마련이다. 기업은 이에 효율적으로 대처하고자 재고를 비축하거나 처분하는 과정에서 생산을 조정하기 때문에 재고수준의 변동은 단기적인 경기순환을 나타내는 중요한 지표로 인식된다. 생산자제품재고지수는 생산자가 보유하고 있는 원재료, 반제품, 재공품을 제외한 완제품 재고의 변동을 파악하기 위한 것으로서 월말 재고수준을 나타내는 경기후행지표이다. 통계청은 매월 광업·제조업 동향조사를 통하여 534개 품목을 조사하여 생산제품재고지수를 작성하여 공표하고 있다.','','ㅅㅅㅈㅈㅍㅈㄱㅈㅅ',ARRAY['경기종합지수']::text[]),
(288,'생산자제품출하지수/생산자출하지수','생산자제품출하지수는 생산자의 판매활동과 광업, 제조업, 전기·가스업 및 수도사업 제품의 출하 동향을 나타내는 지표이다.','생산자제품출하지수는 생산자의 판매활동과 광업, 제조업, 전기·가스업 및 수도사업 제품의 출하 동향을 나타내는 지표이다. 여기서 제품 출하란 생산된 제품을 판매 등의 목적으로 공장 관할 밖의 외부로 출고하는 것을 의미한다. 따라서 보관만을 위하여 공장 내 창고, 타 지역에 있는 자기창고나 타인창고로 이송하는 것은 출하로 보지 않는다. 출하지수는 물건을 생산한 공장에서 물건이 팔려나가는 수준을 나타내며 생산자의 판매활동과 광공업 제품의 수급 동태를 나타내는 실물경제 지표로서 단기 경제동향 분석을 위한 지표로 널리 이용되고 있다. 출하지수는 출하내역에 따라 내수출하지수와 수출출하지수로 구분된다. 이 중 내수용만 집계한 내수출하지수는 현재의 경기상황이 잘 반영되어 경기동행종합지수의 구성 지표로 활용되고 있다.','','ㅅㅅㅈㅈㅍㅊㅎㅈㅅ/ㅅㅅㅈㅊㅎㅈㅅ',ARRAY['경기종합지수']::text[]),
(289,'생산확산지수','광공업생산지수나 서비스업생산지수 등 총량지표로는 파악하기 어려운 전반적인 생산확산의 정도를 측정하는 경제지표이다.','광공업생산지수나 서비스업생산지수 등 총량지표로는 파악하기 어려운 전반적인 생산확산의 정도를 측정하는 경제지표이다. 광공업 생산확산지수는 광공업생산 소분류 업종 (2025년 현재 72개) 중 생산이 전월 대비 “증가 또는 보합인 업종의 수”를 백분비로 산출하고, 서비스업생산확산지수는 서비스업생산 소분류 업종(2025년 현재 85개) 중 생산이 전월 대비 “증가 또는 보합인 업종의 수”를 백분비로 산출한다. 생산확산지수는 0에서 100까지의 범위 값을 갖는데, 지수가 50 이상이면 전월 대비 증가업종의 수가 감소업종의 수보다 많아 확산도 측면에서 본 생산경기가 확장국면에 있음을 의미한다. 통계청은 2007년 2월부터 제조업부문에 한정하여 생산확산지수를 공표하다가, 2009년 7월부터광공업 및 서비스업 생산확산지수를 공표하고 있다. 증가 업종수 + (보합*업종수×0.5) 생산확산지수 = ×100 전체 업종 수 * 보합: -0.05% < 증감률 < 0.05%','','ㅅㅅㅎㅅㅈㅅ',ARRAY['경기종합지수']::text[]),
(290,'생성형 인공지능(AI)','인공지능, 소위 AI(Artificial Intelligence)는 인간의 학습, 추론, 문제해결, 지각, 의사결정 등 능력을 인공적으로 구현하는 컴퓨터과학의 한 분야로 인간의 지능을 컴퓨터를…','인공지능, 소위 AI(Artificial Intelligence)는 인간의 학습, 추론, 문제해결, 지각, 의사결정 등 능력을 인공적으로 구현하는 컴퓨터과학의 한 분야로 인간의 지능을 컴퓨터를 비롯한 여러 장치에 적용한다. 웹검색 기능, 개인비서 서비스, 자율주행장비 등으로 나타나 고 있다. AI는 1956년 미국 다트머스(Dartmouth) 회의에서 등장한 용어로 학문적 과정의 서비스수지하나로 시작되었으나 이후 과잉기대, 자금조달 문제 등으로 부침을 겪었다. 2020년대 들어 생성형(generative) AI가 발전하면서 AI 붐이 형성되었다. 생성형 AI는 텍스트, 이미지, 음악, 코드 등 새로운 콘텐츠를 생성하는 AI 기술로 기존 AI가 데이터를 분석하거나 분류하는데 중점을 둔 것과 차이가 있다. GPT, DALL-E, Sora 등이 대표적이며 교육, 의 료, 마케팅, 대고객서비스, 개발 및 연구 분야에서 널리 활용되고 있다. 생성형 AI의 대두는 허위정보 생산, 콘텐츠 조작, 사이버 범죄, 저작권 문제 등 의도하지 않은 결과와 피해를 초래하기도 하였다. 생성형 AI가 인류에 미칠 장기적 효과, 잠재적 능력에 대한 고찰이 진행되면서 도덕적 문제를 포함한 여러 쟁점이 제기되었으며 혜택 확대와 함께 기술안전확보 방안 등에 대해 많은 논의가 이루어지고 있다.','','ㅅㅅㅎㅇㄱㅈㄴ()','{}'::text[]),
(291,'생활물가지수','생활물가지수(CPI for living necessaries)는 체감물가를 파악하기 위해 일상생활에서 구입 빈도가 높고 지출비중이 높아 가격변동을 민감하게 느끼는 생활필수품을 대상으로 작성한…','생활물가지수(CPI for living necessaries)는 체감물가를 파악하기 위해 일상생활에서 구입 빈도가 높고 지출비중이 높아 가격변동을 민감하게 느끼는 생활필수품을 대상으로 작성한 지수이다. 개별 소비자들이 느끼는 물가는 개인이 구입하는 품목이나 구입 빈도에 따라 각각 달라 2025년 현재 소비지출비중이 큰 458개 품목의 가격변동을 평균하여 작성하는 소비자물가지수와는 차이가 있다. 통계청은 이러한 지수물가와 체감물가와의 차이를 설명하기 위하여 일반소비자들이 자주 구입하는 품목과 기본생필품을 중심으로 144 개 품목(쌀, 달걀, 배추, 소주 등)을 선정하여 생활물가지수를 작성하고 있다.','','ㅅㅎㅁㄱㅈㅅ',ARRAY['물가지수','소비자물가지수(CPI)']::text[]),
(292,'서비스수지','국제수지표에서 서비스수지란 외국과의 서비스거래 결과 벌어들인 돈과 지급한 돈의 차이를 말한다.','국제수지표에서 서비스수지란 외국과의 서비스거래 결과 벌어들인 돈과 지급한 돈의 차이를 말한다. 서비스거래는 가공, 운송, 여행, 건설, 보험, 금융, 통신, 지식재산권, 유지보수, 정부서비스, 기타사업서비스 등의 항목으로 이루어진다. 서비스수지는 거래항목별로 수입과 지급으로 나누어 계상한다. 예를 들어 우리나라의 선박이나 항공기가 상품을 나르고 외국으로부터 받은 운임, 외국관광객이 쓰고 간 외화, 무역대리점의 수출입 알선수수료 수입 등이 서비스 수입으로 기록된다. 반대로 우리나라가 외국에 지급한 선박과 항공기의 운항경비, 해외여행 경비, 기술용역 대가 등은 모두 서비스 지급으로 나타난다. 서비스수지는 상품수지, 본원소득수지, 이전소득수지와 함께 경상수지를 구성한다.','','ㅅㅂㅅㅅㅈ',ARRAY['경상수지']::text[]),
(293,'서킷브레이커','과열된 전기회로를 차단하는 안전장치에서 유래된 용어로 주식시장에서 주가의 급등락시 주식거래를 일시 정지시켜 시장에 미치는 충격을 완화하기 위한 ‘매매거래중단 제도’ 를 의미한다.','과열된 전기회로를 차단하는 안전장치에서 유래된 용어로 주식시장에서 주가의 급등락시 주식거래를 일시 정지시켜 시장에 미치는 충격을 완화하기 위한 ‘매매거래중단 제도’ 를 의미한다. 서킷브레이커(Circuit Breakers)는 1987년 10월 미국 증권시장 사상 최악의 주가 대폭락 사태를 기록한 ‘블랙 먼데이’ 이후 뉴욕증권거래소를 시발로 각국 증시에 시장 안전장치의 하나로 도입되었다. 우리나라에는 주식시장의 일일 가격제한폭이 확대됨에 따라 투자자 보호를 위하여 1998년 12월 도입되었으며, 현물주식과 선물옵션의 모든 거래를 중단시키는 현물 서킷브레이커와 선물옵션 거래만 중단시키는 선물 서킷브레이크로 구분된다. 현물 서킷브레이커는 2015년 개정 이후 단계별로 발동된다. 구분 발동기준1) 내용 1단계 전일 대비 8% 이상 하락 20분간 매매거래중단전일 대비 15% 이상 하락 2단계2) 20분간 매매거래중단 1단계 서킷브레이커 발동시점 대비 1% 이상 추가 하락전일 대비 20% 이상 하락 3단계2) 당일 장종료 조치 2단계 서킷브레이커 발동시점 대비 1% 이상 추가 하락주석: 1) 1분간 지속시 발동 2) 발동기준 동시 충족 필요','','ㅅㅋㅂㄹㅇㅋ','{}'::text[]),
(294,'서학개미','서학개미란 해외, 주로 미국 주식에 직접 투자하는 한국 개인투자자를 일컫는 신조어이 다.','서학개미란 해외, 주로 미국 주식에 직접 투자하는 한국 개인투자자를 일컫는 신조어이 다. ‘서학’은 서양(특히 미국), ‘개미’는 소액을 모아 투자하는 개인투자자를 비유한 표현이 다. 서학개미는 동학개미와 대비되어 생겨난 용어이다. 동학개미는 2020년 코로나19 당시 국내 증시가 급락했을 때 개인투자자들이 대규모 매수에 나서며 증시 방어 역할을 한 선물환거래현상을 동학농민운동에 빗대어 표현한 신조어다. 2022년 이후 국내 주식시장이 부진해지는 반면 미국 주식시장은 미달러화 강세, 빅테크 기업 성장 등을 배경으로 호조를 지속하자 국내시장에 실망한 개인투자자들이 미국 등 해외 주식투자를 크게 확대해 나갔는데 이 러한 개인투자자들을 서학개미라 일컫게 되었다. 서학개미의 활발한 해외 투자는 달러화수요를 크게 증가시켜 환율상승 요인으로 작용하는 등 국내 외환시장의 변동성을 확대시키는 요인 중 하나로 평가된다.','','ㅅㅎㄱㅁ','{}'::text[]),
(295,'선물거래','선물거래(Futures Transactions)란 공인된 거래소에서 품질, 규격 등이 표준화된 상품의 매매계약을 체결하고 일정기간이 경과한 후에 상품의 인수도와 결제가 이루어지는 거래로서…','선물거래(Futures Transactions)란 공인된 거래소에서 품질, 규격 등이 표준화된 상품의 매매계약을 체결하고 일정기간이 경과한 후에 상품의 인수도와 결제가 이루어지는 거래로서 매매계약의 성립과 동시에 상품의 인수도와 결제가 이루어지는 현물거래와 구분된 다. 선물거래와 유사한 개념으로 선도계약(forward contracts)이 있다. 선도계약과 선물거래는 기초 상품을 미래의 특정시점에 특정가격으로 사고 팔기로 약정한 계약이라는 점에서 동일한 성격을 가지나 일반적으로 선도계약은 장외시장에서 거래가 이루어지는 반면 선물거래는 정형화된 거래소를 통해 거래가 이루어지고 일일정산한다는 데 차이가 있다. 선물거래대상이 되는 상품에는 곡물, 귀금속, 원유 등 일반상품과 통화, 채권, 주식 등 금융상품이 있다. 선물거래의 특징으로는 ① 거래소에서 정한 표준화된 조건으로 거래가 이루어지므로 거래의 유동성이 높고, ② 모든 거래자는 거래 이행을 보증하기 위해 청산소(clearing house)에 일정 수준 이상의 증거금(margin)을 예치하여야 하며, ③ 거래소에서 거래가 이루어지면 별도의 조직인 청산소가 거래의 결제 및 이행을 보증하므로 계약불이행 위험(default risk)이 거의 없으며, ④ 최종선물가격을 기준으로 가격변동에 따른당일 손익을 매일 정산한다.','','ㅅㅁㄱㄹ',ARRAY['옵션','스왑']::text[]),
(296,'선물환거래','선물환거래란 계약일로부터 통상 2영업일 경과 후 특정일에 외환의 인수도와 결제가 이 루어지는 거래를 말한다.','선물환거래란 계약일로부터 통상 2영업일 경과 후 특정일에 외환의 인수도와 결제가 이 루어지는 거래를 말한다. 선물환거래는 현재 시점에서 약정한 가격으로 미래 시점에 결제하게 되므로 선물환계약을 체결하면 약정된 결제일까지 거래상대방의 결제가 이연된 다는 점에서 현물환거래와 구별된다. 선물환거래는 주로 환리스크를 헤지하기 위한 목적으로 이용되는데, 예를 들어 6개월 이후에 달러로 대금을 받을 예정인 수출기업은 은행과 6개월 후 달러를 매각하는 대신 원화를 받는 선물환계약을 체결함으로써 원/달러 환율 변동에 따른 환위험을 헤지(hedge)할 수 있다. 이외에도 선물환거래는 금리차익(arbitrage) 획득과 투기적 목적 등으로도 이용되고 있다. 선물환거래는 일방적인 선물환 매입 또는 매도 거래만 발생하는 Outright Forward 거래와 선물환거래가 스왑거래의 일부분으로 현물환거래와 함께 일어나는 Swap Forward 거래로 구분되며, Outright Forward 거래는 다시 만기시점에 실물의 인수도가 일어나는 일반 선물환거래와 만기시점에 실물의 인수도 없이 차액만을 정산하는 차액결제선물환(NDF; Non-Deliverable Forward) 거래로 나눌 수 있다.','','ㅅㅁㅎㄱㄹ',ARRAY['차액결제선물환(NDF) 거래']::text[]),
(297,'선물환포지션비율 규제','선물환포지션비율 규제는 국내은행과 외국은행 지점의 선물환포지션(선물 외화자산에서 선물 외화부채를 뺀 값)을 자기자본의 일정 비율 이내로 제한하는 규제로 2010년 10월부터 시행된 제도이다.','선물환포지션비율 규제는 국내은행과 외국은행 지점의 선물환포지션(선물 외화자산에서 선물 외화부채를 뺀 값)을 자기자본의 일정 비율 이내로 제한하는 규제로 2010년 10월부터 시행된 제도이다. 2006년 이후 국내은행 및 외은지점의 선물환 거래가 급증한 것이 단기외채 급증을 가져와 2008년 글로벌 금융위기 당시 외환시장 불안과 자본유출입 변동성 확대의 주된 원인으로 지적되었다. 이에 따라 거시건전성 강화와 외환시장 안정, 단기외채 증가 억제를 목표로 선물환포지션비율 규제 제도가 도입되었다. 도입 당시 국내은행 50%, 외국은행 지점 250%였던 선물환포지션비율 한도는 외환 및 금융시장 상황에 따라 수차례 조정되어 왔으며 2024년 12월 20일부터 각각 75%, 375%로 상향되었는데이는 국내은행들이 외화유동성을 보다 원활하게 확보할 수 있도록 하는 조치였다. 이처럼 선물환포지션비율 규제는 외환건전성 관리의 핵심 정책수단으로 사용됐으며 최근에 는 글로벌 환율변동성 확대와 외환수급 불안에 대응하기 위해 한도가 점차 완화되는 추세에 있다. 선행종합지수','','ㅅㅁㅎㅍㅈㅅㅂㅇㄱㅈ','{}'::text[]),
(298,'선불카드/선불전자지급수단','선불형카드는 이용고객이 전자적 또는 자기적 방법으로 일정금액을 저장한 카드를 카드발행자로부터 구입하여 상품구매 또는 서비스 이용시마다 대금이 자동으로 차감 지급되도록 한 카드로서 사용범위에 따라…','선불형카드는 이용고객이 전자적 또는 자기적 방법으로 일정금액을 저장한 카드를 카드발행자로부터 구입하여 상품구매 또는 서비스 이용시마다 대금이 자동으로 차감 지급되도록 한 카드로서 사용범위에 따라 범용 선불형카드와 단일목적 선불형카드로 구분된 다. 범용 선불형카드는 광범위한 지역에서 상품 또는 서비스 대금의 지급에 사용될 수 있는 반면 단일목적 선불형카드는 일정지역 또는 특정목적으로만 사용될 수 있다. 선불형카드는 신용카드사가 발행하는 선불카드와 은행 등 금융기관이 발행하는 전자화폐, 전자금융업자가 발행하는 선불전자지급수단으로 구분된다. 대부분의 신용카드사들은 사용한도 가 미리 정해져 있어 그 범위내에서 일반 신용카드처럼 물건이나 서비스를 구매할 수 있고 재충전(top-up)도 가능한 기명 선불카드 또는 무기명 선불카드(기프트카드)를 발행하고 있다. 선불전자지급수단은 IC카드형과 네트워크형으로 분류할 수 있는데 IC카드형은 주로 교통부문을 중심으로 이용되고 있으며 네트워크형은 사이버쇼핑몰 등의 대금결제에 ㅅ 주로 사용되고 있다.','','ㅅㅂㅋㄷ/ㅅㅂㅈㅈㅈㄱㅅㄷ',ARRAY['지급수단','직불카드','전자화폐']::text[]),
(299,'선행종합지수','개별 경제지표로는 파악하기 어려운 국민경제의 총체적인 경기수준을 파악하기 위하여경기종합지수를 작성한다.','개별 경제지표로는 파악하기 어려운 국민경제의 총체적인 경기수준을 파악하기 위하여경기종합지수를 작성한다. 경기종합지수는 선행종합지수, 동행종합지수, 후행종합지수 3 개가 작성되고 있으며, 기준년도 수치가 100이 되도록 하여 산출하고 있다. 선행종합지수는 제조업 재고순환지표, 기계류내수출하지수, 국제원자재가격지수, 수출입물가비율, 코스피지수, 장단기금리차, 구인구직비율, 건설주수액, 소비자기대지수 등의 지표처럼 실제경기순환에 앞서 변동하는 개별지표를 가공·종합하여 만든 지수로 향후 경기변동의 단기예측에 이용된다.','','ㅅㅎㅈㅎㅈㅅ',ARRAY['국내총생산(GDP)','연쇄가중법']::text[]),
(300,'세계경제포럼(다보스포럼)','세계경제포럼(WEF, 다보스포럼)은 저명한 기업인, 경제학자, 언론인, 정치인들이 모여세계 경제를 개선하기 위한 과제를 토론하고 연구하는 회의체이다.','세계경제포럼(WEF, 다보스포럼)은 저명한 기업인, 경제학자, 언론인, 정치인들이 모여세계 경제를 개선하기 위한 과제를 토론하고 연구하는 회의체이다. 본부는 스위스 제네바에 있으나 매년 1~2월경 스위스 동부의 다보스에서 연차총회가 개최되기 때문에 다보스포럼(Davos Forum)이라고도 불린다. 1971년 클라우스 슈바브(Klaus Schwab) 교수에 의해 창설되어 비영리재단 형태로 운영되고 있다. 애초에는 유럽의 기업경영자들이 참석하는 유럽경영포럼(European Management Forum)으로 출발하였으나 1973년부터참석 대상을 전 세계로 확대한 데 이어 1974년에는 정치지도자를 처음으로 초청하였다.','','ㅅㄱㄱㅈㅍㄹ(ㄷㅂㅅㅍㄹ)','{}'::text[]),
(301,'세계국채지수(WGBI)','1976년에 회원 기준을 세계의 1,000개 선도 기업으로 하는 회원제도를 도입하였고 1987년에는 명칭을 세계경제포럼(WEF; World Economic Forum)으로 변경하였다.','1976년에 회원 기준을 세계의 1,000개 선도 기업으로 하는 회원제도를 도입하였고 1987년에는 명칭을 세계경제포럼(WEF; World Economic Forum)으로 변경하였다. WEF는 초청된 인사들에게만 참석을 허용하고 초청받지 않은 참석자는 적지 않은 참석비를 내야 하는 등 배타적인 모임의 성격을 갖고 있다. WEF는 연차총회 외에 지역별, 산업별 회의를 운영하고 있는데 2004년 6월 서울에서 지역별 회의(WEF 아시아 전략회의)가 개최된 바 있다. 2025년에는 세계경제포럼과의 협약에 따라 경기도에 4차산업혁명센터가 설립되었다. WEF가 매년 발간하는 주요 보고서로는 글로벌 리스크 보고서, 글로벌 성별격차 보고서, 미래 직업 보고서 등이 있다. 세계국채지수(WGBI) 세계국채지수(WGBI)는 영국의 FTSE 러셀이 발표하고 있는 주요국 국채로 구성된 국채지수로서 미국 등 주요 선진국 국채를 포함하고 있는 대표적인 채권부문 글로벌 지수이 다. 특히, WGBI는 블룸버그·바클레이즈 글로벌 종합지수(BBGA) 및 JP Morgan 신흥국국채지수(GBI-EM) 등과 함께 세계 3대 채권지수로 분류되고 있으며, 추종자금의 규모 및구성 종목의 안정성 등의 측면에서 대표적인 채권부문 선진국 지수로 알려져 있다. 2025 년 7월 말 현재 WGBI는 주요 선진국 및 중국, 멕시코, 말레이시아 등 총 25개국 국채를 포함하고 있으며, 각 국별 지수 비중은 해당국 국채 시가총액 비중에 따라 결정된다. WGBI 신규 편입은 매년 두 차례 진행되는 정기 리뷰 과정을 통해 진행된다. 일반적인 경우 편입가능성이 높을 것으로 예상되는 국가는 FTSE 러셀의 채권시장 국가분류 보고서의 WGBI 관찰대상국 리스트에 등재되며, 이후 편입기준 충족 여부를 확인한 후 정식 편입 발표가 진행된다. FTSE 러셀이 제시하고 있는 WGBI 편입기준은 시장 규모 및 국가 신용도 등 정량적 기준과 더불어 해당국 시장접근성을 평가하고 있는 정성적 기준이 적용된다. 예를 들어 신규 편입을 위해서는 국채 발행잔액 기준(500억달러) 및 국가 신용등급(S&P 기준 ‘A-’) 등의 최소 조건을 충족하여야 하며, 시장접근성 기준의 경우에는 FTSE의 채권시장 국가분류 레벨 ‘2’이상의 등급이 요구된다. 한국 국채는 2026년 4월부터 지수에 편입되기 시작하여 2026년 11월에 최종 편입이 완료될 예정이다. 대표적인 선진 채권지수인 WGBI 편입은 관','','ㅅㄱㄱㅊㅈㅅ()',ARRAY['국채 신뢰도']::text[]),
(302,'세계무역기구(WTO)','세계무역기구(WTO)는 국제무역 확대, 회원국 간의 통상분쟁 해결, 세계교역 및 새로운통상 논점에 관한 연구를 위하여 설립된 국제기구로서 본부는 스위스 제네바에 있다.','세계무역기구(WTO)는 국제무역 확대, 회원국 간의 통상분쟁 해결, 세계교역 및 새로운통상 논점에 관한 연구를 위하여 설립된 국제기구로서 본부는 스위스 제네바에 있다. 기존 GATT 체제의 문제점 해결을 위한 우루과이라운드 협상을 거쳐 1995년 1월 1일 출범하였다. 설립 이전 회원국들의 GATT 의무 이행이 미흡했던 점을 감안하여 WTO(World Trade Organization)는 GATT에 없던 세계무역분쟁 조정, 관세인하 요구, 반덤핑규제등 준사법적 권한과 구속력을 행사할 수 있는 기능을 갖추고 있다. 또한 협정 형태이던 GATT와 달리 WTO는 여러 하위 기구를 갖춘 국제기구로서 GATT 체제에서 제외되었던서비스, 지적재산권을 포괄하는 등 국제 무역규범의 적용 범위를 크게 확대하였다. WTO 는 각료회의, 일반이사회, 사무국 등의 조직으로 구성되어 있다. 모든 회원국의 대표로 구성되는 각료회의는 2년마다 최소 1회 이상 개최되고, 일반이사회는 각료회의 비회기 중각료회의의 기능을 수행함과 아울러 분쟁해결기구, 무역정책검토기구로서의 기능도 수행한다. 우리나라는 1995년 출범 당시 가입하였고 2025년 9월 현재 회원국은 166개국으로, 회원국들은 전 세계 교역량의 98%를 차지하고 있다.','','ㅅㄱㅁㅇㄱㄱ()','{}'::text[]),
(303,'세계은행(World Bank)','세계은행그룹(World Bank Group)을 구성하는 5개 기구 중에서 국제부흥개발은행 (IBRD)과 국제개발협회(IDA)를 합쳐서 부르는 명칭이다.','세계은행그룹(World Bank Group)을 구성하는 5개 기구 중에서 국제부흥개발은행 (IBRD)과 국제개발협회(IDA)를 합쳐서 부르는 명칭이다. IBRD는 제2차 세계대전으로 인한 재해 복구 및 개발도상국의 경제개발을 위한 장기개발자금 지원을 목적으로 1945 년 12월 설립되었으며 미국 워싱턴에 본부를 두고 있다. IBRD와 IDA는 별개의 법인체지만 IBRD의 임원이 IDA의 임원을 겸임하고 있으며 실무 집행부서도 별도의 구분 없이 세계은행으로 통합되어 운영되고 있다. 설립 초기에는 전쟁 복구 지원에 주력하였으나 이후 저소득 개발도상국의 경제·사회 개발을 위한 장기자금 융자 등 지원 분야를 확대소득교역조건지수하였다. IBRD 가입자격은 국제통화기금(IMF) 회원국에만 부여되고 가입 시 출자금을 납입해야 한다. 2025년 6월 말 현재 회원국은 189개국이며 우리나라는 1955년 8월에 가 입하였다. IDA는 1950년대 후반 최빈개발도상국 지원 필요성이 부각됨에 따라 저소득회원국의 경제개발 촉진 및 생활수준 향상을 위한 자금 지원을 목적으로 1960년 9월 발족하였다. IDA 가입자격은 IBRD 회원국에게만 부여되며 가입 시 출자금을 내야 한다. 2025년 6월 현재 회원국은 174개국이며 우리나라는 1961년 5월에 가입하였다.','','ㅅㄱㅇㅎ()',ARRAY['국제통화기금(IMF)']::text[]),
(304,'소득5분위배율','소득분배의 불평등도를 나타내는 지표의 하나로 전체 가구를 소득 수준의 순서에 따라 20%씩 5등분으로 나눈 다음, 소득 상위 20%(5분위) 계층의 평균소득을 소득 하위 20%(1 ㅅ 분위)…','소득분배의 불평등도를 나타내는 지표의 하나로 전체 가구를 소득 수준의 순서에 따라 20%씩 5등분으로 나눈 다음, 소득 상위 20%(5분위) 계층의 평균소득을 소득 하위 20%(1 ㅅ 분위) 계층의 평균소득으로 나눈 값이다. 소득5분위배율 값이 커질수록 고소득층과 저소득층 간의 소득분배가 악화하였음을 의미한다.','','ㅅㄷㅂㅇㅂㅇ',ARRAY['상대적 빈곤율','지니계수']::text[]),
(305,'소득교역조건지수','소득교역조건지수는 순상품교역조건지수에 수출물량지수를 곱하여 {(수출물가지수/수입물가지수)×수출물량지수} 산출하는 것으로서 수출 총액으로 수입할 수 있는 상품의 양이 기준시점 대비 얼마나…','소득교역조건지수는 순상품교역조건지수에 수출물량지수를 곱하여 {(수출물가지수/수입물가지수)×수출물량지수} 산출하는 것으로서 수출 총액으로 수입할 수 있는 상품의 양이 기준시점 대비 얼마나 증가하였는지를 의미하며 순상품교역조건지수가 가격변동만을 고 려하는 단점을 보완해 준다. 예를 들어, 2024년 12월 소득교역조건지수 118.27은 수출총액으로 수입할 수 있는 상품의 양이 2020년 1~12월의 평균 대비 18.27% 증가하였음 을 의미한다. 순상품교역조건지수와 소득교역조건지수를 동시에 고려하면 수출입 상품의 가격변동뿐만 아니라 수출물량 변동까지 고려할 수 있어 교역조건을 보다 정확히 파악할수 있다.','','ㅅㄷㄱㅇㅈㄱㅈㅅ',ARRAY['순상품교역조건지수']::text[]),
(306,'소득대체율','소득대체율은 은퇴 후 받는 연금수령액이 은퇴 전 소득에 대해 어느 정도 수준인지를 나 타내는 용어이다.','소득대체율은 은퇴 후 받는 연금수령액이 은퇴 전 소득에 대해 어느 정도 수준인지를 나 타내는 용어이다. 노후의 생활수준이 은퇴 전과 비교하여 얼마나 유지될 수 있는지를 평가하는 지표로 이용된다. 예를 들어 은퇴 이전 월평균 소득이 300만원이고 은퇴 이후 매월 연금으로 150만원을 수령한다면 소득대체율은 50%가 된다. 우리나라의 대표적인 사회보장제도인 국민연금의 수령액 정도, 연금제도의 효용성을 평가하는 정책목표로 주로 사용된다. 일반적으로 소득대체율이 지나치게 낮을 경우 은퇴 이후 연금소득으로 생계 유지가 어려워 연금제도의 유용성이 낮게 되고, 반면 너무 높으면 제도의 지속가능성에 문제가 생긴다. 한편 은퇴 이전 소득을 어떻게 정의하느냐에 따라 수치가 크게 달라질 수 있다. 소득세, 자산소득의 포함 여부 등 나라마다 기준이 다르므로 통계 소득대체율 수치를 비교할 때 주의해야 한다.','','ㅅㄷㄷㅊㅇ',ARRAY['사회보장제도','국민연금']::text[]),
(307,'소매판매','소매판매란 여러 유통단계 가운데 최종 소비자인 개인이나 가계를 대상으로 이루어지는 재화의 판매를 말한다.','소매판매란 여러 유통단계 가운데 최종 소비자인 개인이나 가계를 대상으로 이루어지는 재화의 판매를 말한다. 생산자와 유통업자 간의 거래(도매), 기업 간 거래와 달리 최종 수요자인 소비자와의 거래로 소비에 해당한다. 생산자의 자본 지출과 함께 내수 경기의 흐름을 판단하는 데 중요한 역할을 한다. 이러한 소매판매의 동향을 포착하는 지표가 소매판매액지수이다. 소매판매를 담당하는 대형마트, 백화점, 편의점, 온라인 쇼핑몰 등 다양한 유통 채널을 조사하여 작성되고 있다. 소매판매액지수는 업태별 외에 자동차, 가전제품, 의류, 식료품 등 품목별로도 구분 편제되고 있다.','','ㅅㅁㅍㅁ',ARRAY['최종수요/중간수요']::text[]),
(308,'소비의 비가역성','소비행태를 설명하는 상대소득가설은 소비가 현재소득 이외에도 과거의 최고 소득수준또는 타인의 소비수준과 같은 상대적인 요인에 의해서도 영향을 받을 수 있다는 가능성을','소비행태를 설명하는 상대소득가설은 소비가 현재소득 이외에도 과거의 최고 소득수준또는 타인의 소비수준과 같은 상대적인 요인에 의해서도 영향을 받을 수 있다는 가능성을','','ㅅㅂㅇㅂㄱㅇㅅ','{}'::text[]),
(309,'소비자동향지수(CSI)','고려한다.','고려한다. 이 가설에 따르면 현재소득이 과거의 최고 소득수준에 비해 작아지더라도 소비자는 소비를 소득감소에 비례하여 줄이지 않고 이보다 작은 폭으로 줄이게 되는 소비의 비가역성이 발생하게 된다. 이러한 소비의 비가역성으로 인해 발생하는 톱니효과 (Ratchet effect)는 단기적으로 소득이 변동할 경우 한계소비성향은 일정하지만 평균소비성향은 낮아지는 소비행태를 설명하는 핵심요소로 작용한다. 아울러 장기적으로 소득이 늘어날 경우 평균 및 한계소비성향이 같아지는 장기소비 행태도 설명 가능하다. 참고 로 상대소득가설에서 타인의 소비수준에 영향을 받는 현상인 전시효과(Demonstration effect)도 장단기 소비행태를 설명하는데 유용한 개념이라 하겠다.','','ㅅㅂㅈㄷㅎㅈㅅ()',ARRAY['경제심리지수','기업경기실사지수(BSI)']::text[]),
(310,'소비자물가지수(CPI)','일반 가구가 소비생활을 유지하기 위하여 구입하는 각종 상품과 서비스의 가격변동을 종합적으로 파악하기 위하여 작성되는 물가지표이다.','일반 가구가 소비생활을 유지하기 위하여 구입하는 각종 상품과 서비스의 가격변동을 종합적으로 파악하기 위하여 작성되는 물가지표이다. 우리나라의 소비자물가지수는 통계청에서 작성하고 있으며 기준년을 100으로 하여 작성된다. 조사대상 상품 및 서비스의 구성과 가중치도 경제상황에 맞게 주기적으로 조정된다. 2025년 현재는 가계의 총소비지출에 서 구입비중이 큰 458여개의 상품 및 서비스 품목을 대상으로 조사된 소비자 구입가격을 기준으로 하고 있다. 소비자물가지수는 소비자가 일정한 생활수준을 유지하는 데 필요한 소득내지 소비금액의 변동을 나타내기 때문에 소비자의 구매력과 생계비 등의 측정에 사용된다. 또한 소비자물가지수의 상승은 실질임금의 하락을 의미하므로 이를 보전하기 위한 임금인상의 기초자료로 널리 이용되고 있다.','','ㅅㅂㅈㅁㄱㅈㅅ()',ARRAY['생산자물가지수(PPI)','인플레이션']::text[]),
(311,'소비자심리지수','소비자를 대상으로 경기에 대한 판단이나 전망 등을 조사하여 지수화한 경제심리지표를 말한다.','소비자를 대상으로 경기에 대한 판단이나 전망 등을 조사하여 지수화한 경제심리지표를 말한다. 이는 경제주체들의 경기에 대한 판단, 전망 등이 국민경제에 영향을 미친다는 사실에 근거하여 경기상황을 판단하고 미래의 경기를 예측하는 방법이다. 한국은행은 2005 년 1/4분기부터 소비자심리지수(CCSI; Composite Consumer Sentiment Index)를 작성하여 발표하고 있다. 소비자심리지수는 소비자들의 경제에 대한 전반적인 인식을 종합적으로 파악할 수 있는 종합지수로서, 개별 소비자동향지수(CSI) 가운데 관련 경제지표와 연관성이 높은 생활형편지수, 경제상황지수, 가계수입 및 소비지출 전망 등의 지표를 표준화하고 합성하여 산출한다. 따라서 기존의 경제지표가 포착하기 어려운 경제주체의 심리적 변화를 측정할 수 있어 유용하고, 경기 변화를 신속하게 포착할 수 있으며 양적인 통계에서 입수하기 어려운 정보도 조사할 수 있는 특징이 있다. 지수의 기준치는 100이며 100을 초과할 경우 소비자들이 현재의 경기를 과거 평균 수준보다 좋아진 것으로 평가하고 있음을 의미하고, 100 미만은 현재의 경기가 과거 평균적인 경기상황보다 좋지 않음을 나타낸다.','','ㅅㅂㅈㅅㄹㅈㅅ',ARRAY['경제심리지수','기업경기실사지수(BSI)']::text[]),
(312,'소액지급시스템','소액지급시스템(Retail Payment System)은 주로 기업이나 개인의 소액거래를 처리하는 지급시스템으로서 주로 계좌이체지시나 지급카드, 수표, 지로 등을 이용하여 처리된 다.','소액지급시스템(Retail Payment System)은 주로 기업이나 개인의 소액거래를 처리하는 지급시스템으로서 주로 계좌이체지시나 지급카드, 수표, 지로 등을 이용하여 처리된 다. 소액지급시스템은 거래 대상이 광범위하고 지급건수가 매우 많아 건수와 결제유동성을 줄일 수 있는 차액결제방식을 이용하는 것이 일반적이며 참가기관의 차액결제 불이행사태에 대비하여 순신용한도 설정, 사전담보 제공, 손실공동분담제 등과 같은 리스크 관리제도를 두는 경우가 많다. 우리나라의 소액지급시스템은 금융결제원이 운영하고 있으며 이에는 어음교환시스템, 지로시스템, 금융공동망(CD공동망, 타행환공동망, 직불카드공동망, CMS공동망, 지방은행공동망, 전자금융공동망, 전자화폐공동망, 국가간ATM공동망)과 전자상거래 지급시스템 등이 있다.','','ㅅㅇㅈㄱㅅㅅㅌ',ARRAY['거액지급시스템','지급결제시스템','전자화폐']::text[]),
(313,'소프트랜딩/하드랜딩','소프트랜딩(연착륙)은 높은 성장세를 보이는 호황기 경제가 큰 충격 없이 점진적으로 둔화되어 안정되는 것을 말한다.','소프트랜딩(연착륙)은 높은 성장세를 보이는 호황기 경제가 큰 충격 없이 점진적으로 둔화되어 안정되는 것을 말한다. 반대로 하드랜딩(경착륙)은 갑작스러운 정책 변경이나 외부 충격으로 고성장 경제가 급격하게 침체 상태로 빠지는 것을 의미한다. 경기 순환과 통화정책 운용의 평가 과정에서 경기 흐름을 설명하기 위해 주로 사용되고 있다. 또한 높은 인플레이션 상황에서 급격한 경기침체나 실업 증가를 야기하지 않으면서 성장률을 낮추기 위한 정책 운용과 연관된 단어이다. 원래 비행기의 착륙이나 우주선의 궤도 진입 기법과 관련된 용어로 경제학자들이 비유적으로 사용하기 시작하였다. 소프트랜딩은 미국경제가 호황이던 1980년대 연방준비제도이사회(Board of Governors of the Federal Reserve System)가 성장세를 크게 해치지 않으면서 인플레이션 상황을 타개하기 위한 금리 인상을 설명하면서 역사적으로 처음 사용되었다. 호황과 불황이 순환하는 자본주의 경제가 호황국면에서 적절한 정책 운용을 통해 투자심리 위축, 실질소득 감소로 인한 소비부진 등의 부작용을 최소화하는 상황과 관련된다.','','ㅅㅍㅌㄹㄷ/ㅎㄷㄹㄷ',ARRAY['경기','최종수요/중간수요']::text[]),
(314,'소형모듈원자로(SMR)','소형모듈원자로(Small Modular Reactor)는 기존 대형 원전(1,000~1,500MW 출력)보다 출력 규모를 줄이고, 공장에서 모듈 단위로 제작한 뒤 현장에서 조립·설치하는 방식의…','소형모듈원자로(Small Modular Reactor)는 기존 대형 원전(1,000~1,500MW 출력)보다 출력 규모를 줄이고, 공장에서 모듈 단위로 제작한 뒤 현장에서 조립·설치하는 방식의 원자력 발전소를 말한다. 원자로, 증기발생기, 냉각재 펌프, 가압기 등 주요 기기를 하나의 용기에 일체화한 소형 원자로이다. 일반적으로 출력은 300MW(국제원자력기구 기준 소형) 이하로 설계되며, 모듈화된 구조로 건설 기간을 단축하고 비용을 절감할 수 있다. SMR은 소규모 전력망 지역이나 산업 단지 등 다양한 수요에 맞춤형 공급이 가능하다. 또한 풍력, 태양광 등 재생에너지의 간헐성을 보완하는 이산화탄소 배출이 없는 백업 전원으로 활용이 가능하여 탄소중립 목표달성에도 기여할 수 있다. 외부 전력으로 냉각펌프를 작동시켜야 하는 대형 원전과는 달리 자연 순환 냉각방법을 이용하므로 안전성도 높다. 이런 장점으로 인해 주요국은 SMR 기술개발과 실증, 상용화를 위해 연구개발투자를 확대하고 있다.','','ㅅㅎㅁㄷㅇㅈㄹ()','{}'::text[]),
(315,'속물효과(스놉효과)','개성을 추구하는 사람들은 단지 다른 사람들이 많이 구입한다는 이유만으로 특정 물품을 구입하지 않거나 심지어 자신의 옷과 똑같은 옷을 입은 사람을 보면 그 옷을 더 이상 입지 않는다.','개성을 추구하는 사람들은 단지 다른 사람들이 많이 구입한다는 이유만으로 특정 물품을 구입하지 않거나 심지어 자신의 옷과 똑같은 옷을 입은 사람을 보면 그 옷을 더 이상 입지 않는다. 명품브랜드 소비에서 흔히 일어나는 현상인데 이를 속물효과 또는 스놉효과 (Snob Effect)라고 한다. 즉 특정 상품을 소비하는 사람이 많아질수록 그 상품에 대한 수요는 줄어들고 값이 오르면 오히려 수요가 늘어난다. 이 용어는 1950년 레이번슈타인(H. Leibenstein)에 의해 스놉(재산과 지위로 거만을 떠는 속물)이 선호하는 브랜드 물품이 일반 구매층까지 영향을 미치는 현상을 지칭하는 데 처음 사용되었다. 이와는 반대로 전시효과는 상품을 소비하는 사람이 많아질수록 수요도 증가하는 경우를 가리킨다.','','ㅅㅁㅎㄱ(ㅅㄴㅎㄱ)',ARRAY['기펜재','밴드웨건효과','베블런효과']::text[]),
(316,'수요견인 인플레이션','수요견인 인플레이션(Demand-Pull Inflation)이란 경기과열 등으로 인해 개인들의 재화나 수익률곡선서비스에 대한 수요가 크게 늘면서 상대적으로 부족해진 재화 및 서비스의 물가가…','수요견인 인플레이션(Demand-Pull Inflation)이란 경기과열 등으로 인해 개인들의 재화나 수익률곡선서비스에 대한 수요가 크게 늘면서 상대적으로 부족해진 재화 및 서비스의 물가가 지속적으로 상승하게 되는 것을 말한다. 수요견인 인플레이션은 생산요소시장과 생산물시장 모두에서 초과수요가 발생할 때 특히 분명하게 나타난다. 확대재정정책, 과도한 통화량 증가, 민간소비나 투자의 갑작스러운 변동에 따른 수요충격 등은 총수요를 증가시켜 수요견인 인플레이션을 발생시킨다. 예컨대 정부가 침체에 빠진 경기를 부양하기 위해서 정부지출을 확대하고 세율을 인하하는 등의 급격한 확대재정정책을 시행하였다면 총수요가 증가하여 수요견인 인플레이션이 발생할 수 있다.','','ㅅㅇㄱㅇㅇㅍㄹㅇㅅ',ARRAY['비용인상 인플레이션']::text[]),
(317,'수요탄력성','상품의 가격 변화비율에 대한 수요량의 변화비율을 수요의 가격탄력성(price elasticity ㅅ of demand)이라 한다.','상품의 가격 변화비율에 대한 수요량의 변화비율을 수요의 가격탄력성(price elasticity ㅅ of demand)이라 한다. 탄력성은 반응의 크기를 분석하는 데 의미가 있다. 충격을 주는 쪽과 반응하는 쪽의 변화율을 비교하여 같은 경우를 단위 탄력적이라고 하고, 반응하는 쪽의 변화율이 더 높으면 탄력적, 작으면 비탄력적이라고 한다. 수요의 가격탄력성의 경우, 한 상품의 가격의 변화비율과 수요량의 변화비율이 동일할 경우 수요의 가격탄력성은 1이 되며, 이 경우 수요가 단위 탄력적이라고 한다. 수요량의 변화비율이 가격의 변화비율보다 작아서 수요의 가격탄력성이 1보다 작으면 수요가 비탄력적이라고 한다. 반면수요량의 변화비율이 가격의 변화비율보다 높아서 수요의 가격탄력성이 1보다 크게 되면수요가 탄력적이라고 한다.','','ㅅㅇㅌㄹㅅ',ARRAY['공급탄력성']::text[]),
(318,'수익률곡선','이자율 기간구조(term structure)를 그래프로 나타낸 것을 수익률곡선(Yield Curve)이 라고 한다.','이자율 기간구조(term structure)를 그래프로 나타낸 것을 수익률곡선(Yield Curve)이 라고 한다. 이는 채권의 수익률을 만기가 단기인 채권부터 장기인 채권 순으로 나열하여연결한 곡선이다. 가로축은 채권 만기, 세로축은 채권 수익률을 표시하는 평면에서 수익률 수준을 나타낸다. 수익률곡선의 모양은 이자율에 대한 기대에 의존한다. 장기 이자율이 단기 이자율보다 크게 높은 가파른 기울기의 우상향 수익률곡선은 미래에 이자율이 상승할 것으로 기대됨을 의미한다. 반대로 장기 이자율이 단기 이자율보다 낮은 우하향수익률곡선은 이자율이 하락할 것으로 예상함을 시사한다. 이자율은 경기 침체에 반응하여 하락하는 경향이 있으므로, 우하향 수익률곡선은 경제성장률 하락에 대한 예상으로 해석되기도 한다.','','ㅅㅇㄹㄱㅅ',ARRAY['장단기금리차']::text[]),
(319,'수입유발계수','최종수요가 한 단위 증가할 때 각 산업부문에서 직·간접으로 유발되는 수입액 단위를 말하는 것으로 형태에 따라 산업별 수입유발계수와 최종수요항목별 수입유발계수로 나뉜다.','최종수요가 한 단위 증가할 때 각 산업부문에서 직·간접으로 유발되는 수입액 단위를 말하는 것으로 형태에 따라 산업별 수입유발계수와 최종수요항목별 수입유발계수로 나뉜다. 산업별 수입유발계수는 수입투입계수표에 생산유발계수표를 곱하여 구하고 최종수요 항목별 수입유발계수는 소비, 투자, 수출 등 항목별 최종수요에 의한 수입유발액을 최종수요액으로 나누어 산출한다.','','ㅅㅇㅇㅂㄱㅅ',ARRAY['생산유발효과']::text[]),
(320,'수출경합도지수','특정 국가(Z)에 상품을 수출하는 두 국가(X와 Y)의 수출구조가 비슷할수록 경쟁도가 커진다는 가정하에서 이들 국가가 Z국 시장에서 직면하는 경쟁의 정도를 측정하는 지표이다.','특정 국가(Z)에 상품을 수출하는 두 국가(X와 Y)의 수출구조가 비슷할수록 경쟁도가 커진다는 가정하에서 이들 국가가 Z국 시장에서 직면하는 경쟁의 정도를 측정하는 지표이다. 동 지수는 X국과 Y국의 특정 상품이 각각의 총수출에서 차지하는 비중을 비교하여 작은 값을 선택하되 모든 상품에 대해 합산한 후 100을 곱하여 계산한다. 따라서 수출경합도지수(ESI; Export Similarity Index)가 100으로 두 국가의 수출구조가 완전히 일치하면 경쟁도가 가장 높은 상황에 있음을, 반대로 지수가 0으로 두 국가의 수출구조가 완전히 다 르면 경쟁도가 가장 낮은 상태에 있음을 각각 의미하게 된다.','','ㅅㅊㄱㅎㄷㅈㅅ',ARRAY['현시비교우위지수(RCA)']::text[]);
